-- 06-apply-rewrites.sql — apply the reviewed rewrites from rewrites/proposals.json. ONE transaction.
-- NOT run by its author. Review rewrites/review.md and rewrites/proposals.json first.
--
-- What it does
--   * 467 proposals in proposals.json; 147 are WRONG_PLACE (left unchanged, not in this file);
--     the other 320 are written here: REWRITE (new text) or CLEAR (field set to an empty string).
--   * A field is changed ONLY when its current text is still exactly the reviewed "old" text.
--     Anything edited since the review is skipped and reported as 'changed-since-review'.
--   * Backup first: the full rows of every destination / translation touched are copied once into the
--     PRIVATE schema audit_backup (RLS on, no grants to anon/authenticated/public). A second run keeps
--     the first backup and changes 0 fields (status 'already-applied').
--   * fix_log records the result of every proposal; the final checks compare every touched row with the
--     backup (JSON structure, stop names/ids, row status, no placeholder tokens). Any failure raises an
--     exception and NOTHING is committed.
--   * Rollback: see the section at the end of this file (commented out; run it on its own).
--
-- Prerequisites: 01-helper.sql (translation_fix.jsonb_shape and translation_fix.identity_values).
-- Run with psql -v ON_ERROR_STOP=1 -f 06-apply-rewrites.sql, or paste the whole file into the SQL editor.

begin;

do $$
begin
  if to_regprocedure('translation_fix.jsonb_shape(jsonb)') is null
     or to_regprocedure('translation_fix.identity_values(jsonb)') is null then
    raise exception 'Helper missing: run 01-helper.sql first';
  end if;
end $$;

-- ============================================================================================
-- 1. Private backup schema and the reviewed proposals (stored so the rollback can use them).
-- ============================================================================================
create schema if not exists audit_backup;
revoke all on schema audit_backup from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on schema audit_backup from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on schema audit_backup from authenticated';
  end if;
end $$;

create table if not exists audit_backup.rewrites_20261122_proposals (
  locale   text   not null,
  slug     text   not null,
  field    text   not null,
  col      text   not null,   -- destinations column (tagline, seo_description, travel_plan) or 'fields'
  path     text[],            -- JSON path inside travel_plan / fields; null for plain columns
  decision text   not null check (decision in ('REWRITE', 'CLEAR')),
  old_text text   not null,
  new_text text   not null,   -- '' for CLEAR
  primary key (locale, slug, field)
);

insert into audit_backup.rewrites_20261122_proposals (locale, slug, field, col, path, decision, old_text, new_text)
values
  ('de', 'aeolian-islands', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Die Aeolian Islands (ee-OH-lee-ən; italienisch: Isole Eolie [ˈiːzole eˈɔːlje]; sizilianisch: Ìsuli Eoli), manchmal auch als Lipari-Inseln oder Lipari-Gruppe (LIP-ər-ee, italienisch: [ˈliːpari]) nach ihrer größten Insel bezeichnet, sind ein vulkanisches Archipel im Tyrrhenischen Meer nördlich von Sizilien, das nach Aeolus benannt werden soll, dem mythischen Herrscher der Winde. Die Bewohner der Inseln sind als Äoler bekannt (italienisch: Eoliani). Die Inseln hatten eine ständige Bevölkerung von 14.224 bei der Volkszählung [datiert Quelle]; die letzte offizielle Schätzung ist 15.419 zum 1. Januar [datiert Quelle]. Die Aeolian Islands sind im Sommer ein beliebtes Touristenziel und ziehen jährlich bis zu 600.000 Besucher an.', 'Die Äolischen Inseln, nach ihrer größten Insel auch Liparische Inseln genannt, sind ein vulkanischer Archipel im Tyrrhenischen Meer nördlich von Sizilien. Ihr Name soll auf Aiolos zurückgehen, den mythischen Herrscher der Winde. Die Bewohner heißen Äolier (italienisch: Eoliani). Im Sommer sind die Inseln ein beliebtes Reiseziel und ziehen jährlich bis zu 600.000 Besucher an.'),
  ('de', 'albanian-alps-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Alpen von Albanien Nationalpark ist der größte Nationalpark in Albanien. Der in [datierter Quelle] eingerichtete Nationalpark liegt im Norden Albaniens und umfasst eine Fläche von 8.844,65 ha. Die prominenteste Gebirgskette sind die albanischen Alpen, die auch der Namensgeber des Nationalparks sind. Die meisten Gipfel Albaniens über 2.000 m befinden sich hier, darunter der höchste Gipfel der Dinariden, Maja e Jezercës. Die geologische Formation wird von hohem Gelände dominiert, während sie eine Vielzahl von natürlichen Merkmalen hat, darunter Gletscher, Täler, Flüsse, Berge, Wasserfälle, dichte Wälder und mehrere Felsformationen. Es zeichnet sich durch seine sehr abgelegenen Gebiete aus, die ein großes erhaltenes Ökosystem haben, das in erster Linie von unberührter Qualität unberührt ist. Der Park wurde gegründet, um verschiedene Ökosysteme und Biodiversität sowie das kulturelle und historische Erbe der Region zu schützen. Die Region wurde auch als ein wichtiges Vogel- und Pflanzengebiet identifiziert.', 'Der Nationalpark Albanische Alpen ist der größte Nationalpark Albaniens. Er liegt im Norden des Landes und umfasst 8.844,65 Hektar. Prägend sind die Albanischen Alpen, nach denen der Park benannt ist: Hier liegen die meisten Gipfel Albaniens über 2.000 m, darunter die Maja e Jezercës, der höchste Berg der Dinariden. Das hohe, vielfältige Gelände bietet Gletscher, Täler, Flüsse, Wasserfälle, dichte Wälder und Felsformationen; in sehr abgelegenen Gebieten ist das Ökosystem weitgehend unberührt. Der Park schützt Ökosysteme, Artenvielfalt und das kulturelle Erbe der Region und gilt zudem als bedeutendes Vogel- und Pflanzengebiet.'),
  ('de', 'ariege-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Mit rund 2.468 km2 umfasst es 138 Gemeinden seit dem 1. Januar [datiert Quelle] und 46.000 Einwohner.', 'Ein regionaler Naturpark von rund 2.468 km2, der etwa 40 % des Departements Ariège in den Pyrenäen einnimmt.'),
  ('de', 'basque-coast-unesco-global-geopark', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Baskische Küsten-Geopark (baskische Sprache: Euskal Kostaldeko Geoparkea), formell Basque Coast UNESCO Global Geopark, ist ein Gebiet des Baskenlandes im Norden Spaniens, das Mitglied des Europäischen Geopark-Netzwerks in [datierter Quelle] wurde, einem von mehreren globalen Geoparks in Spanien. Es umfasst 89 Quadratkilometer Landschaft mit einer 23 km langen Klippenküste am Golf von Biskaya. Im Landesinneren besteht es aus einem hügeligen Land, das bis zu Sesiarte reicht, das 755 m über dem Meeresspiegel liegt. Die wichtigsten Gemeinden im Geopark sind Zumaia, Deba und Mutriku. Die A8 Cantabrian Autobahn verläuft Ost-West durch den Geopark.', 'Der Geopark Baskische Küste (baskisch: Euskal Kostaldeko Geoparkea), offiziell UNESCO Global Geopark Baskische Küste, liegt im Baskenland im Norden Spaniens und gehört zum Europäischen Geopark-Netzwerk. Er umfasst 89 Quadratkilometer Land mit einer 23 km langen Steilküste am Golf von Biskaya. Im Hinterland steigt das Hügelland bis zum 755 m hohen Sesiarte an. Die wichtigsten Orte sind Zumaia, Deba und Mutriku; die Autobahn A8 durchquert den Geopark von Ost nach West.'),
  ('de', 'bieszczady-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Bieszczady National Park ist der drittgrößte Nationalpark Polens in der Subkarpaten-Woiwodschaft in der äußersten südöstlichen Ecke des Landes. In [datiert Quelle] wurde der Nationalpark ein UNESCO-Weltkulturerbe .', 'Der Bieszczady-Nationalpark ist der drittgrößte Nationalpark Polens. Er liegt in der Woiwodschaft Karpatenvorland, ganz im Südosten des Landes.'),
  ('de', 'bieszczady-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datiert Quelle] wurde der Nationalpark ein UNESCO-Weltkulturerbe .', 'Der Bieszczady-Nationalpark ist der drittgrößte Nationalpark Polens, ganz im Südosten des Landes.'),
  ('de', 'black-forest-central-north-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Mittel-/Nordschwarzwald (deutsch: Naturpark Schwarzwald Mitte/Nord) liegt in Baden-Württemberg. Es umfasst eine Fläche von 3.750 km2 und wurde im Dezember gegründet [datiert Quelle]. Ab [datiert Quelle] ist es der drittgrößte Naturpark in Deutschland.', 'Der Naturpark Schwarzwald Mitte/Nord liegt in Baden-Württemberg und umfasst eine Fläche von 3.750 km2.'),
  ('de', 'breheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Breheimen National Park ist ein Nationalpark, der in [datierter Quelle] eingerichtet wurde. Der Park befindet sich in der Gemeinde Skjåk und der Gemeinde Lom im Kreis Innlandet und in der Gemeinde Luster im Kreis Vestland, Norwegen. Der Park umfasst 1.671 Quadratkilometer des Breheimer Gebirges. Der Park umfasst einige der feuchtesten und trockensten Landschaften des Landes, mit Landschaften, die über Hunderttausende von Jahren von Gletschern, Lawinen und anderen geologischen Prozessen geformt wurden. Besucher begegnen alles von üppigen transhumanzbewirtschafteten Tälern bis hin zu kargen Plateaus, aufsteigenden Gipfeln und aktiven Gletschern.', 'Der Breheimen-Nationalpark liegt in den Gemeinden Skjåk und Lom (Provinz Innlandet) sowie in Luster (Provinz Vestland) in Norwegen. Er umfasst 1.671 Quadratkilometer des Gebirgszugs Breheimen mit einigen der nassesten und trockensten Landschaften des Landes, die über Hunderttausende von Jahren von Gletschern, Lawinen und anderen geologischen Prozessen geformt wurden. Besucher erleben grüne Täler mit Almwirtschaft ebenso wie karge Hochebenen, hohe Gipfel und aktive Gletscher.'),
  ('de', 'breheimen-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Breheimen National Park ist ein Nationalpark, der in [datierter Quelle] eingerichtet wurde.', 'Der Breheimen-Nationalpark umfasst 1.671 Quadratkilometer des Gebirgszugs Breheimen in Norwegen.'),
  ('de', 'catalan-pyrenees-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Regionale Naturpark der katalanischen Pyrenäen ist ein Schutzgebiet im westlichen Drittel des französischen Departements der östlichen Pyrenäen. Gegründet im März [datiert Quelle], ist es der erste regionale Naturpark in den Pyrenäen.', 'Der Regionale Naturpark der Katalanischen Pyrenäen ist ein Schutzgebiet im westlichen Drittel des französischen Departements Pyrénées-Orientales. Er ist der erste regionale Naturpark der Pyrenäen.'),
  ('de', 'catalan-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Gegründet im März [datiert Quelle], ist es der erste regionale Naturpark in den Pyrenäen.', 'Der erste regionale Naturpark der Pyrenäen umfasst das westliche Drittel des Departements Pyrénées-Orientales.'),
  ('de', 'caves-of-barac', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Die Caves of Barać auch bekannt als Barać Höhlen oder Barać Höhlen sind eine Gruppe von Höhlen in der Nähe des Dorfes Nova Kršlja in der Gemeinde Rakovica, Kroatien. Im Jahr 1892 wurden die Höhlen für Besucher geöffnet, aber nach dem Zweiten Weltkrieg verlassen und vergessen. Im Juli [datiert Quelle] die Upper Caves of Barać wurden wieder für Besucher geöffnet.', 'Die Barać-Höhlen sind eine Höhlengruppe beim Dorf Nova Kršlja in der Gemeinde Rakovica in Kroatien. 1892 wurden sie für Besucher geöffnet, nach dem Zweiten Weltkrieg jedoch aufgegeben und vergessen. Die Oberen Barać-Höhlen wurden später wieder für Besucher geöffnet.'),
  ('de', 'conca-dorupatrimoniogolfe-de-saint-florent', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Conca d''Oru, die Weinberge von Patrimonio - Golf von Saint-Florent, erhielt im März das Label Grand Site of France [datiert Quelle]. Es ist der siebzehnte gekennzeichnete Ort und der zweite in Korsika.', 'Conca d''Oru, die Weinberge von Patrimonio und der Golf von Saint-Florent tragen das Label Grand Site de France. Es ist die siebzehnte ausgezeichnete Stätte Frankreichs und die zweite auf Korsika.'),
  ('de', 'faerder-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Færder National Park ist ein Nationalpark in der Gemeinde Færder in Vestfold, Norwegen. Es ist hauptsächlich ein Meerespark und umfasst einige Inseln und Küstengebiete östlich der größeren Inseln Nøtterøy und Tjøme. Im Osten grenzt der Nationalpark an den Ytre Hvaler Nationalpark. Færder umfasst eine Fläche von 340 km2, davon 325 km2 Meer und 15 km2 Land. Der Park wurde am 23. August gegründet [datiert Quelle]. Der Park umfasst große Teile des Archipels von Bolærne sowie den geschützten Leuchtturm Færder und die Ruinen des Store Færder Lighthouse mit seinen zugehörigen geschützten Gebäuden.', 'Der Færder-Nationalpark liegt in der Gemeinde Færder in der Provinz Vestfold in Norwegen. Er ist überwiegend ein Meeresnationalpark mit Inseln und Küstenabschnitten östlich der größeren Inseln Nøtterøy und Tjøme und grenzt im Osten an den Ytre-Hvaler-Nationalpark. Færder umfasst 340 km2, davon 325 km2 Meer und 15 km2 Land. Zum Park gehören große Teile des Bolærne-Archipels, der denkmalgeschützte Leuchtturm Færder sowie die Ruinen des Leuchtturms Store Færder mit seinen geschützten Nebengebäuden.'),
  ('de', 'garrawilla-national-park-nsw', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Garrawilla National Park wurde im Dezember [datiert Quelle] erstellt. Es umfasst eine Fläche von 937 Hektar. Dieser Park liegt auf der nördlichen Seite des Oxley Highway etwa auf halbem Weg zwischen Coonabarabran und Mullaley in New South Wales, Australien.', 'Der Garrawilla-Nationalpark umfasst 937 Hektar. Er liegt an der Nordseite des Oxley Highway, etwa auf halbem Weg zwischen Coonabarabran und Mullaley in New South Wales, Australien.'),
  ('de', 'garrawilla-national-park-nsw', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Garrawilla National Park wurde im Dezember [datiert Quelle] erstellt.', 'Der Garrawilla-Nationalpark liegt am Oxley Highway zwischen Coonabarabran und Mullaley in New South Wales.'),
  ('de', 'grands-causses-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Parc naturel régional des Grands Causses ist ein französischer Naturpark, der am 6. Mai 1995 gegründet und in [datierter Quelle] erneuert wurde. Es liegt in Occitanie, an der Südspitze des Zentralmassivs und umfasst den südlichen Teil des Departements Aveyron und den nördlichen Teil des Departements Hérault.', 'Der Parc naturel régional des Grands Causses ist ein französischer Regionaler Naturpark, der am 6. Mai 1995 gegründet wurde. Er liegt in Okzitanien am Südrand des Zentralmassivs und umfasst den Süden des Departements Aveyron und den Norden des Departements Hérault.'),
  ('de', 'guadarrama-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sierra de Guadarrama National Park (auf Spanisch: Parque Nacional de la Sierra de Guadarrama) ist ein Nationalpark in Spanien mit einer Fläche von fast 34.000 Hektar, der fünftgrößte in Spaniens Nationalparksystem. Die Guadarrama-Bergkette (Sistema Central) enthält einige ökologisch wertvolle Gebiete in der Gemeinschaft Madrid und Kastilien und León (Provinzen Segovia und Ávila). Das Gesetz, das den kürzlich genehmigten Nationalpark regelt, wurde am 26. Juni in der BOE veröffentlicht [datiert Quelle] ([datiert Quelle]-06-26).', 'Der Nationalpark Sierra de Guadarrama (spanisch: Parque Nacional de la Sierra de Guadarrama) umfasst knapp 34.000 Hektar und ist der fünftgrößte Nationalpark Spaniens. Das Gebirge Guadarrama (Sistema Central) birgt ökologisch wertvolle Gebiete in der Region Madrid und in Kastilien-León (Provinzen Segovia und Ávila).'),
  ('de', 'hump-ridge-track', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Hump Ridge Track, auch Tuatapere Hump Ridge Track genannt, ist ein 60-62 km langer Wanderweg, der teilweise im Fiordland National Park in Neuseeland liegt. Der Track wurde in [datierter Quelle] eröffnet und wird privat im Auftrag des Tuatapere Hump Ridge Track Charitable Trust betrieben.', 'Der Hump Ridge Track, auch Tuatapere Hump Ridge Track genannt, ist ein 60 bis 62 km langer Wanderweg, der teilweise im Fiordland-Nationalpark in Neuseeland verläuft. Er wird privat im Auftrag des Tuatapere Hump Ridge Track Charitable Trust betrieben.'),
  ('de', 'junkerdal-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der 682 Quadratkilometer große Park wurde in [datierter Quelle] eröffnet.', 'Ein 682 km2 großer Nationalpark in Saltdal und Fauske in der Provinz Nordland, an der Grenze zu Schweden.'),
  ('de', 'kosterhavet-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Kosterhavet National Park ist der erste nationale Meerespark in Schweden, der im September eingeweiht wurde [datiert Quelle]. Es ist Teil des Skagerrak-Meeres und befindet sich in den Gemeinden Strömstad und Tanum in Bohuslän, Västra Götaland, Schweden. Es besteht aus dem Meer und den Küsten rund um die Koster-Inseln, mit Ausnahme von allem anderen auf den Inseln. Im Norden grenzt er an den norwegischen Marinepark Ytre Hvaler.', 'Der Kosterhavet-Nationalpark ist der erste Meeresnationalpark Schwedens. Er gehört zum Skagerrak und liegt in den Gemeinden Strömstad und Tanum in Bohuslän (Provinz Västra Götaland). Er umfasst das Meer und die Uferzonen rund um die Koster-Inseln, nicht aber das übrige Inselland, und grenzt im Norden an den norwegischen Meeresnationalpark Ytre Hvaler.'),
  ('de', 'kotychi-and-strofylia-wetlands-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Es wurde ein Nationalpark in [datiert Quelle] erklärt.', 'Geschützte Feuchtgebiete und Wälder in Achaia und Ilia mit dem Kotychi-See, dem Strofylia-Wald und Kap Araxos.'),
  ('de', 'langsua-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Langsua National Park wurde in [datierter Quelle] gegründet. Der Park besteht aus einem Gesamtschutzgebiet von 537,1 Quadratkilometern. Sie liegt im norwegischen Komitat Innlandet und umfasst Teile der Gemeinden Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron und Nord-Fron.', 'Der Langsua-Nationalpark schützt 537,1 Quadratkilometer in der Provinz Innlandet in Norwegen und erstreckt sich über Teile der Gemeinden Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron und Nord-Fron.'),
  ('de', 'langsua-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Langsua National Park wurde in [datierter Quelle] gegründet.', 'Der Langsua-Nationalpark schützt 537,1 Quadratkilometer in der Provinz Innlandet in Norwegen.'),
  ('de', 'les-deux-caps-blanc-nez-gris-nez', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datierter Quelle] erhöht sich sein Umfang von acht auf achtzehn Gemeinden.', 'Ein Grand Site de France an der Opalküste zwischen Boulogne-sur-Mer und Calais, gegenüber von England.'),
  ('de', 'liechtensteinklamm', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Liechtensteinklamm ist täglich von Anfang Mai bis 30. September [datiert Quelle] von 09:00 bis 18:00 Uhr (letzter Eintritt um 18:00 Uhr) geöffnet.', ''),
  ('de', 'liechtensteinklamm', 'tagline', 'fields', '{tagline}'::text[], 'CLEAR', 'Liechtensteinklamm ist täglich von Anfang Mai bis 30. September geöffnet [datiert Quelle] von 09:00 bis 18:00 Uhr (zuletzt)', ''),
  ('de', 'lomsdal-visten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Lomsdal-Visten Nationalpark ist ein norwegischer Nationalpark, der am 26. Juni gegründet wurde [datiert Quelle]. Der Park besteht aus einem Gesamtschutzgebiet von 1.102 Quadratkilometern. Es befindet sich im norwegischen Verwaltungsbezirk Nordland und umfasst Teile der Gemeinde Brønnøy, der Gemeinde Vevelstad, der Gemeinde Grane und der Gemeinde Vefsn.', 'Der Lomsdal-Visten-Nationalpark ist ein norwegischer Nationalpark mit einer Schutzfläche von 1.102 Quadratkilometern. Er liegt in der Provinz Nordland und erstreckt sich über Teile der Gemeinden Brønnøy, Vevelstad, Grane und Vefsn.'),
  ('de', 'loonse-en-drunense-duinen', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Es wurde als Nationalpark seit [datiert Quelle].', 'Ein 35 km2 großer Nationalpark zwischen Tilburg, Waalwijk und ''s-Hertogenbosch im Süden der Niederlande.'),
  ('de', 'lorship-bertiz-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Naturpark Señorío de Bertiz (offiziell Bertizko Jaurerria Parke Naturala) [datiert Quelle] ha, befindet sich', 'Señorío de Bertiz ist ein Naturpark im Nordwesten Navarras in Spanien, ausgewiesen 1984.'),
  ('de', 'marine-natural-park-of-picardy-and-opale-coast', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Parc naturel marin des estuaires picards et de la mer d''Opale ist ein französischer Meeresnaturpark, der im Dezember [dated source] gegründet wurde. Er befindet sich vor den sieben Küstenflüssen, von Süden nach Norden, der Bresle, der Somme, der Authie, der Canche, der Liane, dem Wimereux und der Slack. Sein Hauptsitz befindet sich in Écault auf dem Gebiet von Saint-Étienne-au-Mont, im Pas-de-Calais.', 'Der Parc naturel marin des estuaires picards et de la mer d''Opale ist ein französischer Meeresnaturpark vor den Mündungen von sieben Küstenflüssen: von Süden nach Norden Bresle, Somme, Authie, Canche, Liane, Wimereux und Slack. Sein Sitz ist in Écault in der Gemeinde Saint-Étienne-au-Mont (Pas-de-Calais).'),
  ('de', 'marker-wadden-in-het-markermeer', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Die erste Insel wurde am 24. September eingeweiht [datiert Quelle].', 'Die Marker Wadden sind ein künstlicher Archipel und ein Naturschutzgebiet im Markermeer in den Niederlanden.'),
  ('de', 'midden-delfland', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Midden-Delfland (niederländisch: [ˌmɪdəˈdɛlflɑnt]) ist eine Gemeinde in der Region Westland in der Provinz Südholland in den Niederlanden. Es hatte eine Bevölkerung von 19.355 in [datierter Quelle] und bedeckt eine Fläche von 49,38 km2, von denen 2,19 km2 Wasser sind.', 'Midden-Delfland ist eine Gemeinde in der Region Westland in der Provinz Südholland in den Niederlanden. Sie umfasst 49,38 km2, davon 2,19 km2 Wasserfläche.'),
  ('de', 'midden-delfland', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Es hatte eine Bevölkerung von 19.355 in [datierter Quelle] und bedeckt eine Fläche von 49,38 km2, von denen 2,19 km2 Wasser sind.', 'Midden-Delfland ist eine 49,38 km2 große Gemeinde in der Region Westland in Südholland.'),
  ('de', 'mont-ventoux', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark Mont-Ventoux, in der provenzalischen Pargue dóu Ventours, ist ein regionaler Naturpark, der per Dekret am 28. Juli [datiert Quelle] geschaffen wurde. Es ist der 55. regionale Naturpark in Frankreich und der 9. in der Provence-Alpes-Côte d''Azur.', 'Der Regionale Naturpark Mont-Ventoux (provenzalisch: pargue dóu Ventours) ist der 55. Regionale Naturpark Frankreichs und der 9. in der Region Provence-Alpes-Côte d''Azur.'),
  ('de', 'nationaal-park-de-sallandse-heuvelrug', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datiert Quelle] änderte die niederländische Regierung den Status des Gebiets in Nationalpark.', 'Die Sallandse Heuvelrug ist ein Nationalpark in Overijssel zwischen den Orten Hellendoorn und Holten.'),
  ('de', 'nationaal-park-duinen-van-texel', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Park umfasst etwa 43 km2 und erreichte den Status eines Nationalparks in [datierter Quelle].', 'Der Nationalpark Duinen van Texel umfasst rund 43 km2 Dünen und Küstenebenen auf der Insel Texel.'),
  ('de', 'national-park-drina', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Drina-Nationalpark ist der vierte Nationalpark in Bosnien und Herzegowina und der dritte in der Republika Srpska. Es wurde gegründet in [datiert Quelle]. Die nächste Stadt ist Srebrenica. Es befindet sich auf der anderen Seite der Drina in Bezug auf Tara Nationalpark in Serbien.', 'Der Nationalpark Drina ist der vierte Nationalpark in Bosnien und Herzegowina und der dritte in der Republika Srpska. Die nächstgelegene Stadt ist Srebrenica. Er liegt am gegenüberliegenden Ufer der Drina, gegenüber dem Tara-Nationalpark in Serbien.'),
  ('de', 'national-park-of-eastern-macedonia-and-thrace', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Nationalpark Ostmazedonien - Thrakien wurde in [datierter Quelle] gegründet und umfasste die bereits geschützten Gebiete von D. Nestos, L. Vistonidas, L. Ismaridas und deren weitere Gebiete. Der Feuchtgebietskomplex des Nationalparks ist aufgrund seiner großen Fläche und seines großen biologischen, ästhetischen, wissenschaftlichen, geomorphologischen und pädagogischen Wertes einer der wichtigsten in Griechenland. Ziel des Nationalparks ist es, Lebensräume und seltene Flora- und Faunaarten, die in der Region endemisch sind und brüten, effektiv zu schützen.', 'Der Nationalpark Ostmakedonien und Thrakien umfasst das bereits zuvor geschützte Nestos-Delta, den Vistonida-See, den Ismarida-See und ihr weiteres Umland. Sein Feuchtgebietskomplex gehört wegen seiner Größe und seines hohen biologischen, landschaftlichen, wissenschaftlichen, geomorphologischen und pädagogischen Werts zu den bedeutendsten Griechenlands. Ziel des Parks ist der Schutz von Lebensräumen und seltenen Pflanzen- und Tierarten, die in der Region heimisch sind oder hier brüten.'),
  ('de', 'national-park-of-messolonghi-aitoliko-lagoons', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datierter Quelle] erstellt, umfasst es den größten Lagunenkomplex des Landes.', 'Der Nationalpark umfasst den größten Lagunenkomplex Griechenlands am Nordwestende des Golfs von Patras.'),
  ('de', 'nationalpark-mols-bjerge', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mols Bjerge National Park oder Nationalpark Mols Bjerge ist ein dänischer Nationalpark in der Gegend als Mols Bjerge in Syddjurs Gemeinde, Zentraljütland bekannt, am 29. August eingeweiht [datiert Quelle]. Das Schutzgebiet ist 180 Quadratkilometer groß. Die Mols Hills, die eine Höhe von 137 Metern erreichen, sind zentral im Park gelegen und nehmen 2.500 ha ein. "Mehr als die Hälfte aller wilden dänischen Pflanzenarten" findet man bei Mols Bjerge.', 'Der Nationalpark Mols Bjerge ist ein dänischer Nationalpark im Gebiet Mols Bjerge in der Gemeinde Syddjurs in Mitteljütland. Das Schutzgebiet umfasst 180 Quadratkilometer. Im Zentrum liegen die bis zu 137 Meter hohen Mols-Hügel mit 2.500 Hektar. Mehr als die Hälfte aller wild wachsenden Pflanzenarten Dänemarks kommt in Mols Bjerge vor.'),
  ('de', 'nationalpark-thy', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Thy National Park ist ein Nationalparkgebiet in Thy, Dänemark, das am 22. August für die Öffentlichkeit geöffnet wurde [datiert Quelle]. Es liegt im Nordwesten Jütlands, entlang der Küste von Hanstholm nach Agger Tange und erstreckt sich über 55 km von Norden nach Süden und 5-12 km von Osten nach Westen. Die Gesamtfläche des Nationalparks beträgt 244 km2.', 'Der Nationalpark Thy liegt in der Landschaft Thy in Dänemark. Er erstreckt sich in Nordwestjütland entlang der Küste von Hanstholm bis Agger Tange, 55 km von Nord nach Süd und 5 bis 12 km von Ost nach West. Insgesamt umfasst er 244 km2.'),
  ('de', 'natural-park-of-serra-d-irta', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Serra d''Irta (Valencian: Parc Natural de la Serra d''Irta, Spanisch: Parque Natural de la Sierra de Irta) ist ein Naturpark in der valencianischen Gemeinschaft, Südspanien. Es umfasst 7.744 Hektar Land sowie eine Küstenlinie des Meeresnaturreservats des angrenzenden Mittelmeers. Es wurde ein geschütztes Gebiet in [datiert Quelle] erklärt.', 'Der Naturpark Serra d''Irta (valencianisch: Parc Natural de la Serra d''Irta; spanisch: Parque Natural de la Sierra de Irta) liegt in der Valencianischen Gemeinschaft in Spanien. Er umfasst 7.744 Hektar Land sowie ein Meeresschutzgebiet an der angrenzenden Mittelmeerküste.'),
  ('de', 'naturpark-nissum-fjord', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Nissum Fjord wurde als Pilotprojekt auf Anfrage des Nissum Fjord Network im Mai eingerichtet [datiert Quelle]. Der Naturpark erstreckt sich über 22.670 Hektar rund um den Nissum Fjord und ist der drittgrößte Naturpark Dänemarks. Der Naturpark wurde vom Open Air Council am 12. Dezember genehmigt [datiert Quelle].', 'Der Naturpark Nissum Fjord erstreckt sich über 22.670 Hektar rund um den Nissum Fjord und ist der drittgrößte Naturpark Dänemarks.'),
  ('de', 'naturpark-nissum-fjord', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Naturpark wurde vom Open Air Council am 12. Dezember genehmigt [datiert Quelle].', 'Der Naturpark Nissum Fjord umfasst 22.670 Hektar rund um den Fjord – der drittgrößte Naturpark Dänemarks.'),
  ('de', 'north-pindos-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'North Pindos National Park ist 230 km lang und 70 km breit, gegründet in [datierter Quelle] und gilt als eines der wichtigsten Gebiete auf nationaler und europäischer Ebene. Auch die Vielfalt der seltenen Arten sollte erwähnt werden, da fast alle großen Säugetiere des griechischen Festlandes in der Region gehostet werden. Insgesamt 60 Säugetierarten, 166 Vogelarten, 30 Reptilienarten, 14 Amphibienarten und 17 Fischarten sind im Park zu finden.', 'Der Nationalpark Nord-Pindos ist 230 km lang und 70 km breit und gilt als eines der wichtigsten Gebiete Griechenlands und Europas. Fast alle großen Säugetiere des griechischen Festlands leben hier: Insgesamt kommen im Park 60 Säugetier-, 166 Vogel-, 30 Reptilien-, 14 Amphibien- und 17 Fischarten vor.'),
  ('de', 'ostmarka-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Østmarka National Park ist ein norwegischer Nationalpark, der in [datierter Quelle] erstellt wurde. Es umfasst eine Fläche von 54 km2 in Østmarka, Oslo und Akershus Municipality Nordre Follo, Lørenskog, Røllen und Enebakk.', 'Der Østmarka-Nationalpark ist ein norwegischer Nationalpark und umfasst 54 km2 des Waldgebiets Østmarka in Oslo sowie in den Akershus-Gemeinden Nordre Follo, Lørenskog, Rælingen und Enebakk.'),
  ('de', 'paluma-range-national-park-qld', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Am National Parks Day [datiert Quelle] kündigte die Regierung von Queensland die Hinzufügung von 6.510 Hektar zum Paluma Range National Park an.', ''),
  ('de', 'parc-naturel-regional-de-guyane', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Parc naturel régional de la Guyane ist ein französischer regionaler Naturpark, der [dated source] in Guyane gegründet wurde. Er ist in drei terrestrische Teile und zwei maritime Abschnitte unterteilt und umfasst das Gebiet von sechs Kommunen: Iracoubo, Mana, Ouanary, Roura, Saint-Georges und Sinnamary.', 'Der Regionale Naturpark Guayana ist ein französischer Regionaler Naturpark in Französisch-Guayana. Er besteht aus drei Land- und zwei Meeresteilen und erstreckt sich über sechs Gemeinden: Iracoubo, Mana, Ouanary, Roura, Saint-Georges und Sinnamary.'),
  ('de', 'parc-naturel-regional-des-baronnies-provencales', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark der provenzalischen Baronnies erstreckt sich über ein Alpenmassiv zwischen den Departements Drôme und Hautes-Alpes im Südosten Frankreichs. Dieser regionale Naturpark wurde am 26. Januar gegründet [datiert Quelle]. Es umfasst 104 Gemeinden ganz oder teilweise.', 'Der Regionale Naturpark Baronnies provençales erstreckt sich über ein Alpenmassiv zwischen den Departements Drôme und Hautes-Alpes im Südosten Frankreichs. Er umfasst ganz oder teilweise 104 Gemeinden.'),
  ('de', 'parc-naturel-regional-des-baronnies-provencales', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Dieser regionale Naturpark wurde am 26. Januar gegründet [datiert Quelle].', 'Ein regionaler Naturpark in einem Alpenmassiv zwischen Drôme und Hautes-Alpes, der 104 Gemeinden umfasst.'),
  ('de', 'parco-naturale-regionale-bosco-incoronata', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark Bosco Incoronata ist ein geschütztes Naturgebiet, das in [datierter Quelle] entlang des Flusses Cervaro etwa 12 Kilometer von der Stadt Foggia entfernt im Herzen der Apulientafel liegt.', 'Der Regionale Naturpark Bosco Incoronata ist ein Naturschutzgebiet am Fluss Cervaro, etwa 12 Kilometer von Foggia entfernt, mitten in der Tavoliere-Ebene Apuliens.'),
  ('de', 'parco-naturale-regionale-bosco-incoronata', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der regionale Naturpark Bosco Incoronata ist ein Naturschutzgebiet, das in [datierter Quelle] entlang der', 'Ein Naturschutzgebiet am Fluss Cervaro, rund 12 Kilometer von Foggia in Apulien entfernt.'),
  ('de', 'parco-naturale-regionale-del-vulture', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Vulture Regional Natural Park ist ein Naturschutzgebiet, das im November gegründet wurde [datiert Quelle]. Dieser Regionalpark umfasst das Geiergebiet sowie einen Teil der Gemeindegebiete Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte und San Fele, die alle zur Provinz Potenza gehören.', 'Der Regionale Naturpark Vulture ist ein Naturschutzgebiet, das das Gebiet des Vulture und Teile der Gemeinden Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte und San Fele umfasst, alle in der Provinz Potenza.'),
  ('de', 'parco-naturale-regionale-del-vulture', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Vulture Regional Natural Park ist ein Naturschutzgebiet, das im November gegründet wurde [datiert Quelle]. Diese Reg.', 'Ein Naturschutzgebiet rund um den Vulture, mit einem Teil von Melfi, in der Provinz Potenza.'),
  ('de', 'parco-naturale-regionale-terra-delle-gravine', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Terra delle Gravine ist ein Naturschutzgebiet in Apulien in [datierter Quelle]. Das Gebiet umfasst die Provinzen Brindisi und Taranto im Gebiet Murge.', 'Der Naturpark Terra delle Gravine ist ein Naturschutzgebiet in Apulien und umfasst Teile der Provinzen Brindisi und Tarent in der Murgia.'),
  ('de', 'ponga-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Ponta ist ein spanischer Naturschutzraum, der sich im zentralen Bereich des Cantábrica-Gebirges mit einem Schutzgebiet von 20533 ha befindet, und die meisten von ihnen sind der Stadtrat von Ponta. Es sollte am Ende der Periode zuerst in den Reds Park aufgenommen werden und sein Name als Naturpark war später und mit eigener Identität. Es wurde durch Gesetz 4 / [datiert Quelle] erklärt.', 'Der Naturpark Ponga ist ein spanisches Naturschutzgebiet im zentralen Kantabrischen Gebirge mit einer Schutzfläche von 20.533 Hektar, die größtenteils in der Gemeinde Ponga liegt.'),
  ('de', 'reinheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reinheimen National Park ist ein Nationalpark in Norwegen, der in [datierter Quelle] eingerichtet wurde. Der Park besteht aus einem 1.969 Quadratkilometer großen zusammenhängenden geschützten Berggebiet. Es befindet sich in den Provinzen Møre og Romsdal und Innlandet in Norwegen. Der Park umfasst Teile der Gemeinden Lesja, Skjåk, Vågå, Lom, Fjord und Rauma. Der Park besteht aus einem Großteil der Tafjordfjella-Bergkette sowie dem Rentierlebensraum im nördlichen Teil des Ottadalen-Tals.', 'Der Reinheimen-Nationalpark ist ein norwegischer Nationalpark mit einem zusammenhängenden Gebirgsschutzgebiet von 1.969 Quadratkilometern in den Provinzen Møre og Romsdal und Innlandet. Er umfasst Teile der Gemeinden Lesja, Skjåk, Vågå, Lom, Fjord und Rauma, einen Großteil des Gebirges Tafjordfjella sowie die Rentiergebiete im Norden des Ottadalen.'),
  ('de', 'reynisdrangar', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datiert Quelle] Reynisfjara [ˈreiːnɪsˌfjaːra] wurde der sechstbeste Strand der Welt bewertet.', 'Basaltfelsnadeln unter dem Reynisfjall bei Vík í Mýrdal in Südisland, umrahmt von schwarzem Sandstrand.'),
  ('de', 'rohkunborri-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Rohkunborri National Park ist ein Nationalpark im Bezirk Troms, Norwegen, der in [datierter Quelle] eingerichtet wurde. Der Park besteht aus einem 571 Quadratkilometer großen Schutzgebiet und befindet sich in der Gemeinde Bardu an der Grenze zu Schweden, etwa 30 Kilometer südöstlich des Dorfes Setermoen und etwa 50 Kilometer nordöstlich der Stadt Narvik.', 'Der Rohkunborri-Nationalpark liegt in der Provinz Troms in Norwegen und umfasst ein Schutzgebiet von 571 Quadratkilometern. Er befindet sich in der Gemeinde Bardu an der Grenze zu Schweden, etwa 30 Kilometer südöstlich des Dorfes Setermoen und rund 50 Kilometer nordöstlich der Stadt Narvik.'),
  ('de', 'rosalia-kogelberg-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Im Rahmen des Projekts „Barrierefreies Naturerlebnis Rosalia-Kogelberg wurde zwischen [datierter Quelle] und [datierter Quelle] ein Wander- und Naturerlebnis für alle Sinne geschaffen. Das Projekt umfasste unter anderem die Konzeption und den Bau von insgesamt elf barrierefreien Erlebnis- und Ruhestationen entlang des sogenannten Eulenwegs oder entlang der „Tour Teichwiesen.', 'Im Rahmen des Projekts „Barrierefreies Naturerlebnis Rosalia-Kogelberg“ entstand ein Wander- und Naturerlebnis für alle Sinne. Dazu wurden elf barrierefreie Erlebnis- und Raststationen entlang des Eulenwegs und der „Tour Teichwiesen“ geplant und gebaut.'),
  ('de', 'saimaa-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Das Gebiet erhielt den UNESCO Global Geopark Status in [datiert Quelle].', 'Ein UNESCO Global Geopark mit 65 Geotopen rund um den Saimaa, den größten See Finnlands.'),
  ('de', 'salpausselka-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Salpausselkä Geopark wurde am 13. April angenommen [datiert Quelle].', 'Der Salpausselkä-Geopark umfasst Lahti, Hollola, Asikkala, Heinola, Sysma und Padasjoki in Finnland.'),
  ('de', 'sheskinmore-nature-reserve', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sheskinmore Nature Reserve Standort: GPS: Breitengrad: 54.794006 Längengrad: -8.463635 Sheskinmore bezieht sich auf ein großes Gebiet von Sanddünen, See und Sumpf, das zwischen Kiltooris und Ballinreavy Strand liegt, nordwestlich von Ardara, Co. Donegal. Das Gebiet ist als besonderes Schutzgebiet, als besonderes Schutzgebiet und als Wildvögelschutzgebiet ausgewiesen. Das Gebiet ist leicht vom Tor in Mullyvea gegenüber Kiltooris Lough zu erreichen. Ist ceantar mór dumcha, locha agus seascainn é Seascann Mór atá idir Cill Dorais agus Trá Bhaile an Riabhaigh ar thaobh thiar thuaidh d’Ard Ratha, Co. Dhún na nGall. Tá an ceantar ainmnithe mar Cheantar Speisialta Caomhnaithe, mar Cheantar Cosanta Speisialta agus mar Thearmann Éanlaithe. Tá sé furasta dul isteach ann tríd an geata ag Mullach Bheitheach os coinne Loch Chill Dorais. Lebensräume Das Gebiet ist meist ein festes Sanddünensystem, das Machair-Grasland, Dünenschluchten, Sheskinmore-Lough und den umliegenden Sumpf, Fen und Schilf umfasst. Es gibt einige Eiche und Haselpeeling mit Heide auf den trockeneren Nordhängen hinter dem Lough und es gibt auch Küstenheide auf der Carrickalagh Landzunge. Sescen Mór bedeutet wörtlich "großer Sumpf" und die sumpfige Ebene enthält einen Großteil der interessanten Flora und Fauna der Gegend. Südlich und westlich der flachen sumpfigen Ebene gibt es sandige Machair-Grasflächen, die sich zu hohen welligen Sanddünen entlang Trawmore Strand und Ballinreavy Strand entwickeln. Gnáthóga Ist córas duimhche seasta an ceantar seo den chuid mó ina bhfuil talamh féarach, machaire, dumhcha, Loch an tSeascainn Mhóir, machaire moing agus sraith ghiolcach thart air. Tá crainn dharach agus scrobarnach coil maraoin le fraoch ar na fánaí tirime ar an taobh thuaidh den loch agus tá fraoch cósta ar cheann tire Charraig Adhlactha. Ciallaíonn Seascann Mór bogach nó corrach mór agus ta fásra agus ainmhíthe suimiúla le fail ar chuid mhaith den mhachaire corrach seo. Ar an taobh theas agus thiar den mhachaire tá talaimh féir gainimh a éiríonn ansin i ndumhcha droimnigh arda le taobh trá na Trá Móire agus Trá Bhaile an Riabhaigh Vögel Ein Besuch zu jeder Jahreszeit ist immer interessant für die Vogelwelt. Im Winter eine kleine Herde von Greensland White Fronted Gänse fressen hier ungestört. Chough und Twite füttern auch hier im Winter. Brent Goose, Whooper Swan, Wigeon, Tufted Duck, Goldeneye und Golden Plover sind weitere Winterbesucher. Lapwing, Mallard, Teal, Snipe und Mute Swan sind das ganze Jahr über zu finden, ebenso Linnet, Skylark, Meadow Pipit, Stonechat und Reed Bunting. Sommerbesucher sind die Grasshopper, Sedge und Willow Warblers und Wheatear, Swallow und Cuckoo. Raubvögel nutzen diesen riesigen, ungestörten Ort zur Jagd. Ein Ist fiú go mór cuairt a thabhairt anseo ag am ar bith den bhliain chun an éanlaith shuimiúil a fheiceáil. Ich rith an gheimhridgh bíonn scata Géanna le Brollaigh Bhána ón Ghraonlainn a chothú ann. Bionn an Cág Deargchosach agus an Ghleoiseach Shléibhe ann as gheimhreadh. Ist cuairteoirí geimhridgh eile iad an Ghé Dhubh, an Eala Ghlórach, an Lacha rua, an Lacha Dhubh, an Feadóg Shléibhe agus Feadóg na Súile Óire. Chítear an Pilibín, an Mallard, an Phraslacha, an Naoscach, an Eala Bhalbh ann I rith nab liana chomh maith leis an Ghleoiseach, an Fhuiseog, an Riabhógmhóna, an Chloch Dearg agus an Ghealóg Dhúcheannach. Ich rith an tsamhraidh bionn an Dreoilin Teaspaigh, an Chíb, an Ceolaire Sailí, an Chlochrán, an Fhainleog agus an Chuach le feiceáil ann. Úsáideann éin chreiche an láithreán leathan oscaillte seo mar thalamh seilge. Pflanzen Die feste Düne und Machair werden geschafft, ihren Artenreichtum zu verbessern. Rinder weiden nur in den Wintermonaten ausgiebig. Orchideenarten umfassen die Marsh Helleborine, Bee Orchid, Frosch Orchidee und die seltene irische Orchidee. Es gibt eine Abfolge von Farben während der Sommermonate in den Dünen und auf dem Sumpf, von Gelb und Weiß im Frühling bis zu den Rosa und Purpur des Spätsommers. Zu den in der Gegend verzeichneten Seltenheiten gehören das aquatische schlanke Naiad und Pfeifenwort, das winzige Petalwort, auch Quillwort, hoary whitlow Gras und viele Steinwortarten. Plandaí Riaraítear na dumhcha seasta agus an machaire chun siabhreas na ngnéithe a mhéadu. Bíonn eallach ag iníorgo tréan anseo i rith míonna an gheimhridh amháin. Ich measc an ngnéithe magairlíne tá Cuacihín Corraigh, Magairlín na mBeach, Magairlín an Ioscáin agus Magairlín Éireannach atá neamhchoitianta. Bíonn athraithe datha trí mhíonna an t-samhraidh sna dumhcha agus ar an machaire ó dhath buí agus bán an earraigh go dathanna bándearga agus corcra dheireadh an t-samhraidh. Ich measc na ngnéithe neamhchoitianta a rinneadh cuntas orthu sa cheantar seo tá nimfigh uisce, píbín uisce, tursarraing chleite, bosán anagair agus tursarraing chloiche. Tiere Kaninchen, Dachse und Füchse sind die häufigsten Säugetiere in Sheskinmore aufgezeichnet. Otter wurden im lough gesehen. Frosch und Molch brüten in und um die Dünenschluchten und die gewöhnliche Echse brütet an den trockeneren Hängen. Die geschützte kleine Sumpfschneckenart Vertigo geyeri findet sich im Fenlebensraum westlich des Loughs. Die Gegend ist auch bemerkenswert für die Vielfalt der Schmetterlinge und Libellen, die hier brüten. Marsh fritillary und schmuddelige Skipper beide brüten in Sheskinmore zusammen mit 18 anderen Schmetterlingsarten. Sheskinmore Lough und die damit verbundenen Feuchtgebiete sind der artenreichste Standort in Donegal für Libellen und Damselflies. Fünfzehn Arten wurden registriert, die interessanteste ist der Schwarzschwanz-Skimmer und die kleine blaue Spitze. 2 Ainmhithe Ist iad coiníní, broic agus sionnaigh na siní ist coitianta ar an t-Seascann Mór. Chonacthas dobharchúnna sa loch. Bíonn an frog agus an t-earc luachra ag síolrú thart ar na dumhcha agus an t-earc coitianta ag síolrú ar na fánaí tirime. Faightear seilidí beaga corraigh. Vertigo geyeri atá cosanta sa ghnáthóg moinge taobh thiar den loch. Tá cáil ar an cheantar seo as ucht ilghnéitheachta na bhfeileacán agus na snatháidí móra a shíolraíonn anseo. Bíonn Fritileáin corraigh agus Preabairí modartha ag síolrú ar an SEascann Mór maraon le ocht ngné déag d’fheileacán. Bíonn níos mó gnéithe de shnatháidí móra agus cuileoga daimsil le fail I gceantar Loch an t-Seascainn Mhóir agus na talaimh fliucha thart air ná in áit ar bith eile i gCo. Dhún na nGall. Rinneadh cuntas oifigiúil ar cúig ghné déag díobh agus Snatháid an Eireaball Dhuibh agus Snatháid Bheag an Bhairr Ghoirm ar na cinn is suimiúla. Verwaltung Das Grundstück wird von NPWS verwaltet, um seine Biodiversität zu maximieren. Das Gebiet ist reich an Sumpf- und Dünenpflanzen und unterstützt eine Vielzahl von Wirbellosen und Vögeln. Das Getreidefeld am Eingang von Mullyvea wurde zuerst in [datierte Quelle] gepflanzt, um Finken und Buntings während der Wintermonate zu füttern. Ein weiteres Grundstück ist für Sandfield geplant. Die Website ist Winter grasen Blumenvielfalt zu fördern und Kuhpats sind auch eine Quelle der Nahrung für die Nahrungssuche. Die Besatzraten werden regelmäßig überprüft und Pferde können manchmal auf dem Gelände weiden. Zur Bekämpfung von Bracken wurden verschiedene Methoden ausprobiert. Eine Schleuse ist vorhanden, um den Wasserstand am Lough zu kontrollieren, um die schlanke Naiad-Population zu schützen. In [datierter Quelle] McGlincheys Haus in Sandfield wurde vollständig restauriert und wird jetzt als Feldstudienzentrum genutzt. Bainistíocht Riaraíonn an NPWS an eastát se chun uasmhéid éagsúlacht bheatha a fháil. Ist ceantar saibhir é le plandaí seascainn agus dumhcha a chothaíonn éagsúlacht leathan éan agus ainmhíthe gan cnámh droma. Cuireadh arbhar don chéad uair I [datiert Quelle] ag bealach insteach ag Mullach Bheitheach chun na gealóga a bheathú i rith an gheimhridh. Tá plean do phlota eile arbhair ag Achadh an Ghainimh. Cuirtear eallach ag iníor ar an láitrhreán sa gheimhreadh chun cuidiú leis an éagsúlacht bláthanna agus is foinse bia an cac bó do na cáig dhearg-chosacha. Coinnítear súil ar an stoc ó am go ham agus b’fheider go ligtar do chapaill a bheith ar fhéar anseo chomh maith. Úsáideadh dóigheanna éagsúla chun smacht a chur ar an raithneach. Cuireadh loc-chomhla ann chun leibhéil an uisce a chosaint. Ich [datiert Quelle] coíríodh Teach Mhic Loinsigh in Achadh an Ghainimh agus tá sé in úsáid mar ionad staidéir amuigh faoin aer. Zugang & Sicherheit Es gibt drei signierte Access Points. Der Haupteingang befindet sich am Mullyvea-Tor gegenüber dem Kiltooris Lough. Es gibt Zugang von der Ostseite sowohl bei Murveagh und Sandfield der R261. Wanderer sollten vorsichtig sein, Tiere zwischen Oktober und Mai zu weiden, und Hunde sollten jederzeit an der Leine und unter Kontrolle gehalten werden. Ein Teil des Landes auf dem Gelände ist immer noch in Privatbesitz, also achten Sie darauf, Tore zu schließen und keine Mauern oder Zäune zu beschädigen. Entsprechende Wanderkleidung sowie eine Karte und ein Kompass werden empfohlen. Alle schädlichen Aktivitäten sollten NPWS im Gleanveagh-Nationalpark 074 -9137090 oder NPWS in Ballinafad, Co. Sligo, 071 9666700 Bealach Isteach agus Sábháilteacht gemeldet werden. Tá trí bhealach isteach le comharthaí. Tá an príomhbhealach isteach ag geata an Mhullaigh Bheitheach os coinne Loch Chill Dorais. Tá bealach isteach ón taobh thoir ag Muirbheitheach Bheitheach agus Achadh an Ghainimh ón R261. Ba choir do shiúlóirí o bheith cúramach roimh ainmhíthe ar fhéar ó Dheireadh Fómhair go Bealtaine agus ba cheart madaí a choinneáil ar éill agus faoi smacht an t-am uilig. Ná dean dearmad na geataí a dhruid ná dochar a dhéanamh do bhallaí agus do fhálta. Moltar do shiúlóirí éadai foirstineacha a chaítheamh agus léarscáil agus compass a thabhairt leo. Má bhíonn imeachtaí a chuisíonn dochar ba choir fios a chur ar an tSeirbhís Páirceanna Náisiúnta agus Fiadhúlra I nGleann Bheitheach 074-9137090 nó ag Baile an Atha Fada, Co. Shligigh 071- 9666700 Gegründet: Eigentum: Staatseigentum', 'Sheskinmore ist ein großes Gebiet aus Sanddünen, See und Marsch zwischen Kiltooris und dem Strand von Ballinreavy, nordwestlich von Ardara in Co. Donegal. Es ist besonderes Schutzgebiet, Vogelschutzgebiet und Wasservogelreservat und leicht über das Tor in Mullyvea gegenüber dem Kiltooris Lough erreichbar. Das Gelände besteht vor allem aus festliegenden Dünen mit Machair-Grasland, Dünentälern, dem Sheskinmore Lough und den umliegenden Marschen, Niedermooren und Schilfflächen. Im Winter äst hier ein kleiner Trupp Blässgänse, dazu Alpenkrähen und Berghänflinge; zu den Orchideen zählen Sumpf-Stendelwurz, Bienen-Ragwurz und die seltene Irische Orchidee. Das Reservat wird vom NPWS betreut und im Winter beweidet, um die Pflanzenvielfalt zu fördern. Zwischen Oktober und Mai ist auf Weidetiere zu achten; Hunde sind an der Leine zu führen und Tore zu schließen, da ein Teil des Geländes in Privatbesitz ist.'),
  ('de', 'sila-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sila National Park (italienisch: Parco nazionale della Sila) ist ein italienischer Nationalpark in Kalabrien auf dem Sila Plateau. Es wurde 1997 gegründet und umfasst etwa 74.000 Hektar (180.000 Acres). Seine höchsten Berge sind Botte Donato (1.928 m) in Sila Grande und Gariglione (1.764 m) in Sila Piccola. Der Park wurde mit dem Regionalerlass vom 14. November [datiert Quelle] gegründet und umfasst eine eigene Verwaltungsagentur. Der Park umfasst die Gebiete, die früher Teil des Kalabrien-Nationalparks (1968) waren, und schützt Gebiete von großem Umweltinteresse in Sila Piccola, Sila Grande und Sila Greca, für insgesamt 736,95 Quadratkilometer (284,54 Quadratkilometer), in 21 Gemeinden (comuni) und 6 "Berggemeinschaften" (comunità montane) in den drei kalabrischen Provinzen Catanzaro, Cosenza und Crotone.', 'Der Nationalpark Sila (italienisch: Parco nazionale della Sila) liegt in Kalabrien auf der Hochebene der Sila. Er wurde 1997 gegründet und umfasst rund 74.000 Hektar. Die höchsten Berge sind der Botte Donato (1.928 m) in der Sila Grande und der Gariglione (1.764 m) in der Sila Piccola. Der Park schließt Gebiete des früheren Nationalparks Kalabrien (1968) ein und schützt ökologisch wertvolle Landschaften in Sila Piccola, Sila Grande und Sila Greca in 21 Gemeinden der Provinzen Catanzaro, Cosenza und Crotone.'),
  ('de', 'sjunkhatten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sjunkhatten National Park wurde in [datierter Quelle] im Bezirk Nordland, Norwegen, gegründet. Der Park besteht aus einem ständig geschützten 417,5-Quadratkilometer-Gebiet, darunter 39,8-Quadratkilometer-Seegebiet in der Gemeinde Bodø, der Gemeinde Fauske und der Gemeinde Sørfold. Der Park befindet sich auf einer Halbinsel zwischen dem Sørfolda-Fjord und Saltfjord, einschließlich Gletscherlandschaft, Höhlen und Wassersysteme, Fjorde, der große See Heggmovatnet, seltene Tierarten und kulturelles Erbe.', 'Der Sjunkhatten-Nationalpark liegt in der Provinz Nordland in Norwegen. Er ist ein zusammenhängendes Schutzgebiet von 417,5 Quadratkilometern, davon 39,8 Quadratkilometer Meer, in den Gemeinden Bodø, Fauske und Sørfold. Der Park liegt auf einer Halbinsel zwischen dem Sørfolda-Fjord und dem Saltfjord und umfasst eine von Gletschern geformte Landschaft, Höhlen und Gewässersysteme, Fjorde, den großen See Heggmovatnet, seltene Tierarten und Kulturerbe.'),
  ('de', 'sjunkhatten-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Sjunkhatten National Park wurde in [datierter Quelle] im Bezirk Nordland, Norwegen, gegründet.', 'Ein 417,5 km2 großer Nationalpark auf einer Halbinsel zwischen Sørfolda und Saltfjorden in Nordland, Norwegen.'),
  ('de', 'soroya', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sørøya oder Sállan ist Norwegens viertgrößte Insel in Bezug auf die Fläche und die größte in Finnmark. Die 811 Quadratkilometer große Insel ist zwischen der Gemeinde Hasvik und der Gemeinde Hammerfest aufgeteilt. Es wird oft behauptet, "eine der schönsten" der Inseln in Norwegen zu sein. In [datiert Quelle] war die Bevölkerung der Insel 1.100.', 'Sørøya (samisch: Sállan) ist nach Fläche die viertgrößte Insel Norwegens und die größte der Provinz Finnmark. Die 811 Quadratkilometer große Insel ist zwischen den Gemeinden Hasvik und Hammerfest aufgeteilt und gilt oft als „eine der schönsten“ Inseln Norwegens.'),
  ('de', 'southern-black-forest-biosphere-area', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Das Schwarzwald-Biosphärengebiet liegt im Südschwarzwald und wurde in [datierter Quelle] eingerichtet.', 'Ein UNESCO-Biosphärenreservat im Südschwarzwald mit Sitz der Geschäftsstelle in Schönau.'),
  ('de', 'watchmaking-doubs-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark Doubs Horloger ist ein regionaler Naturpark in Ostfrankreich, gegründet am 4. September [datiert Quelle]. Es liegt im Departement Doubs in der Region Burgund-Franche-Comté und erstreckt sich entlang der französisch-schweizerischen Grenze und grenzt an den regionalen Naturpark Doubs auf der Schweizer Seite.', 'Der Regionale Naturpark Doubs Horloger liegt im Osten Frankreichs im Departement Doubs (Region Bourgogne-Franche-Comté). Er erstreckt sich entlang der französisch-schweizerischen Grenze und grenzt auf Schweizer Seite an den Regionalen Naturpark Doubs.'),
  ('en', 'are', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Åre is a locality and one of the leading Scandinavian ski resorts situated in Åre Municipality, Jämtland County, Sweden with 3,200 inhabitants in [dated source]. It is, however, not the seat of the municipality, which is Järpen. 25% of the local economy is based on tourism, most notably the downhill skiing and biking resorts in Åre, Duved and Storlien. The growth in tourism has resulted in the development of hotels, recreational and shopping opportunities in the area.', 'Åre is a locality and one of Scandinavia''s leading ski resorts, in Åre Municipality, Jämtland County, Sweden. It is not the seat of the municipality, which is Järpen. Around 25% of the local economy is based on tourism, notably the downhill skiing and biking resorts in Åre, Duved and Storlien, and the growth in tourism has brought hotels, recreation and shopping to the area.'),
  ('en', 'ariege-pyrenees-regional-natural-park', 'seo_description', 'seo_description', null, 'REWRITE', 'With about 2,468 km2, it includes 138 communes since 1 January [dated source] and 46,000 inhabitants.', 'A regional natural park of about 2,468 km2, covering some 40% of the Ariège department in the Pyrenees.'),
  ('en', 'ariege-pyrenees-regional-natural-park', 'tagline', 'tagline', null, 'REWRITE', 'With about 2,468 km2, it includes 138 communes since 1 January [dated source] and 46,000 inhabitants.', 'A regional natural park of about 2,468 km2, covering some 40% of the Ariège department in the Pyrenees.'),
  ('en', 'baie-de-somme-picardie-maritime', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Bay of Somme Regional Natural Park - Picardie maritime is a regional natural park located in the department of the Somme, created in [dated source] at the initiative of the Hauts-de-France region. This is the 5th natural park in this area.', 'The Bay of Somme – Picardie maritime Regional Natural Park lies in the Somme department and was created at the initiative of the Hauts-de-France region. It is the fifth natural park in this region.'),
  ('en', 'basque-coast-unesco-global-geopark', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Basque Coast Geopark (Basque language: Euskal Kostaldeko Geoparkea), formally the Basque Coast UNESCO Global Geopark, is an area of the Basque Country in the north of Spain which became a member of the European Geoparks Network in [dated source], one of several Global Geoparks in Spain. It comprises 89 square kilometres of countryside with a 23 km long cliffed coast fronting the Bay of Biscay. Inland it comprises hilly country which reaches up to Sesiarte which is 755m above sea level. The main communities within the Geopark are Zumaia, Deba and Mutriku. The A8 Cantabrian motorway runs east–west through the Geopark.', 'The Basque Coast Geopark (Basque: Euskal Kostaldeko Geoparkea), formally the Basque Coast UNESCO Global Geopark, is an area of the Basque Country in northern Spain and a member of the European Geoparks Network, one of several Global Geoparks in Spain. It comprises 89 square kilometres of countryside with a 23 km cliffed coast on the Bay of Biscay. Inland, hilly country rises to Sesiarte at 755 m above sea level. The main communities are Zumaia, Deba and Mutriku, and the A8 Cantabrian motorway crosses the Geopark from east to west.'),
  ('en', 'bieszczady-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source], the national park became a UNESCO World Heritage Site .', 'Bieszczady National Park is Poland''s third-largest national park, in the far southeast of the country.'),
  ('en', 'bieszczady-national-park', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source], the national park became a UNESCO World Heritage Site .', 'Bieszczady National Park is Poland''s third-largest national park, in the far southeast of the country.'),
  ('en', 'black-forest-central-north-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Central/North Black Forest Nature Park (German: Naturpark Schwarzwald Mitte/Nord) is located in Baden-Württemberg in Germany. It covers an area of 3,750 km2 and was founded in December [dated source]. As of [dated source], it is the third-largest nature park in Germany.', 'The Central/North Black Forest Nature Park (German: Naturpark Schwarzwald Mitte/Nord) lies in Baden-Württemberg, Germany, and covers an area of 3,750 km2.'),
  ('en', 'boucles-de-la-seine-normande', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel régional des Boucles de la Seine Normande, formerly Parc naturel régional de Brotonne until [dated source], is a regional natural park created on 17 May 1974 and comprises 35 communes, covering 89,700 hectares, between Rouen and Le Havre. It is composed of 77 communes + 1 associated commune, Sandouville. Three municipalities have the status of entry-gate cities: Canteleu, Yvetot and Pont-Audemer. It has a wide variety of natural and human environments, as it extends over the Roumois, the Risle valley, the banks of the Seine downstream of Rouen with their small tributary valleys, the Brotonne loop, the marshes of the Estuary, the Vernier marsh, and the southern part of the country of Caux. These include:', 'The Parc naturel régional des Boucles de la Seine Normande, formerly the Parc naturel régional de Brotonne, is a regional natural park created on 17 May 1974 between Rouen and Le Havre, covering 89,700 hectares. Canteleu, Yvetot and Pont-Audemer are its gateway towns. It spans a wide variety of natural and human landscapes: the Roumois, the Risle valley, the banks of the Seine downstream of Rouen with their small side valleys, the Brotonne loop, the estuary marshes, the Vernier marsh and the southern Pays de Caux.'),
  ('en', 'breheimen-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Breheimen National Park is a national park that was established in [dated source].', 'Breheimen National Park covers 1,671 square kilometres of the Breheimen mountain range in Norway.'),
  ('en', 'breheimen-national-park', 'tagline', 'tagline', null, 'REWRITE', 'Breheimen National Park is a national park that was established in [dated source].', 'Breheimen National Park covers 1,671 square kilometres of the Breheimen mountain range in Norway.'),
  ('en', 'breheimen-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Breheimen National Park is a national park that was established in [dated source]. The park is located in Skjåk Municipality and Lom Municipality in Innlandet county and in Luster Municipality in Vestland county, Norway. The park covers 1,671 square kilometres of the Breheimen mountain range. The park encompasses some of the wettest and driest terrain in the country, with landscapes shaped over hundreds of thousands of years by glaciers, avalanches and other geological processes. Visitors encounter everything from lush transhumance‑farmed valleys to barren plateaus, soaring peaks and active glaciers.', 'Breheimen National Park lies in Skjåk and Lom municipalities in Innlandet county and in Luster Municipality in Vestland county, Norway. It covers 1,671 square kilometres of the Breheimen mountain range, including some of the wettest and driest terrain in the country, shaped over hundreds of thousands of years by glaciers, avalanches and other geological processes. Visitors find everything from lush valleys with summer farms to barren plateaus, soaring peaks and active glaciers.'),
  ('en', 'catalan-pyrenees-regional-natural-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Created in March [dated source], it is the first regional natural park in the Pyrenean Mountains.', 'The first regional natural park in the Pyrenees, covering the western third of the Pyrénées-Orientales.'),
  ('en', 'catalan-pyrenees-regional-natural-park', 'tagline', 'tagline', null, 'REWRITE', 'Created in March [dated source], it is the first regional natural park in the Pyrenean Mountains.', 'The first regional natural park in the Pyrenees, covering the western third of the Pyrénées-Orientales.'),
  ('en', 'conca-dorupatrimoniogolfe-de-saint-florent', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Conca d''Oru, the vineyards of Patrimonio - Gulf of Saint-Florent, received the Label Grand Site of France in March [dated source]. It is the seventeenth labeled site and the second in Corsica.', 'Conca d''Oru, the vineyards of Patrimonio and the Gulf of Saint-Florent hold the Grand Site de France label. It is the seventeenth labelled site in France and the second in Corsica.'),
  ('en', 'dajti-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Dajti Mountain National Park is a national park established in 1966 in central Albania, spanning an area of 293.84 km2 since [dated source]. The park is 40 km east of the Adriatic Sea and 26 km east of Tirana. The area is under shared jurisdiction between Albanian Agency of Protected Areas and Tirana Municipality Parks and Recreation Agency . It is adjacent to Shtamë Pass Nature Park to the northwest, Kraste-Verjon Protected Landscape to the west, and Mali me Gropa-Bizë-Martanesh Protected Landscape to the east. The park is marked by an extremely fragmented, rugged topography which creates favourable conditions for a great diversity of ecosystems and biodiversity.', 'Dajti Mountain National Park is a national park established in 1966 in central Albania, covering 293.84 km2. It lies 40 km east of the Adriatic Sea and 26 km east of Tirana and is managed jointly by the Albanian Agency of Protected Areas and the Tirana Municipality Parks and Recreation Agency. It borders Shtamë Pass Nature Park to the northwest, Kraste-Verjon Protected Landscape to the west and Mali me Gropa-Bizë-Martanesh Protected Landscape to the east. Its extremely fragmented, rugged topography favours a great diversity of ecosystems and wildlife.'),
  ('en', 'faerder-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Færder National Park is a national park in Færder Municipality in Vestfold county, Norway. It is mostly a marine park, and includes some islands and coastal areas to the east of the larger islands of Nøtterøy and Tjøme. To the east, the national park borders to the Ytre Hvaler National Park. Færder covers an area of 340 km2, of which 325 km2 is sea and 15 km2 is land. The park was established on 23 August [dated source]. The park includes large parts of the archipelago of Bolærne, as well as the protected Færder Lighthouse and the ruins of Store Færder Lighthouse with its associated protected buildings.', 'Færder National Park is a national park in Færder Municipality in Vestfold county, Norway. It is mostly a marine park, including islands and coastal areas east of the larger islands of Nøtterøy and Tjøme, and borders Ytre Hvaler National Park to the east. Færder covers 340 km2, of which 325 km2 is sea and 15 km2 is land. The park includes large parts of the Bolærne archipelago, the protected Færder Lighthouse and the ruins of Store Færder Lighthouse with its associated protected buildings.'),
  ('en', 'garrawilla-national-park-nsw', 'seo_description', 'seo_description', null, 'REWRITE', 'Garrawilla National Park was created in December [dated source].', 'Garrawilla National Park lies beside the Oxley Highway between Coonabarabran and Mullaley in New South Wales.'),
  ('en', 'garrawilla-national-park-nsw', 'tagline', 'tagline', null, 'REWRITE', 'Garrawilla National Park was created in December [dated source].', 'Garrawilla National Park lies beside the Oxley Highway between Coonabarabran and Mullaley in New South Wales.'),
  ('en', 'garrawilla-national-park-nsw', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Garrawilla National Park was created in December [dated source]. It covers an area of 937 hectares. This park is located on the northern side of the Oxley Highway approximately halfway between Coonabarabran and Mullaley in New South Wales, Australia.', 'Garrawilla National Park covers an area of 937 hectares. It lies on the northern side of the Oxley Highway, roughly halfway between Coonabarabran and Mullaley in New South Wales, Australia.'),
  ('en', 'grands-causses-regional-natural-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel régional des Grands Causses is a French regional natural park created on 6 May 1995 and renewed in [dated source]. Located in Occitanie, at the southern tip of the Central Massif, it covers the southern part of the Aveyron department and the northern part of the Hérault department.', 'The Parc naturel régional des Grands Causses is a French regional natural park created on 6 May 1995. Located in Occitanie at the southern tip of the Massif Central, it covers the southern part of the Aveyron department and the northern part of the Hérault department.'),
  ('en', 'harz-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source] Harz became the first National Park in Germany to cover two federal states; the eastern part', 'Harz National Park spans two federal states, from Herzberg to Bad Harzburg and Ilsenburg, rising to 1,141 m on the Brocken.'),
  ('en', 'harz-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'In [dated source] Harz became the first National Park in Germany to cover two federal states; the eastern part in Sachsen-Anhalt consists of 8,900 ha of land and was set up in 1990. In 1994, the federal government of Niedersachsen established the western part of the park, covering 15,800 ha. As a result, the united Harz National Park consists of approximately 24,700 ha. The Park is part of Natura [dated source] – the European nature conservation – network.

Harz National Park stretches from a low mountain range near Herzberg in the southern part of the mountains, across the Harz massif to its northern slopes near Bad Harzburg and Ilsenburg. It offers the entire range of characteristic ecological systems, variations in height, slopes and rocks. Height varies from approximately 240 m in the north and 270 m on the southern edge up to 1,141 m on Brocken peak. The Park offers an ecologically complex landscape and contains different vegetation zones.

Harz National Park is virtually uninhabited, but does contain some settlements. Nearly all the land within the Park is forested and belongs to the federal states.

Scientific research has identified numerous habitats which are, based on Middle-European standards, quite close to a natural state, such as the high and middle regions or zones of the Harz, rocky biotopes, many running waters, and a large beech, spruce and mixed forest area. In some sections, however, ecological changes in afforestation must be carried out in order to get closer to original, natural forest conditions.', 'Harz National Park covers two federal states: the eastern part in Saxony-Anhalt, set up in 1990, has 8,900 ha of land, and the western part, established by Niedersachsen in 1994, covers 15,800 ha. Together the park covers about 24,700 ha and is part of Natura 2000, the European nature conservation network.

The park stretches from the low hills near Herzberg in the south, across the Harz massif, to its northern slopes near Bad Harzburg and Ilsenburg. It spans the full range of characteristic ecosystems, altitudes, slopes and rocks, from about 240 m in the north and 270 m on the southern edge up to 1,141 m on the Brocken, with several vegetation zones.

The park is virtually uninhabited, though it contains a few settlements. Almost all of its land is forested and owned by the federal states.

Research has identified many habitats that are close to a natural state by Central European standards, such as the high and middle zones of the Harz, rocky biotopes, many streams and a large area of beech, spruce and mixed forest. In some sections, however, forest management is still needed to bring the forest closer to its original natural condition.'),
  ('en', 'hump-ridge-track', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Hump Ridge Track, also called the Tuatapere Hump Ridge Track, is a 60–62 km walking track that is partly in Fiordland National Park in New Zealand. The track was opened in [dated source] and is run privately on behalf of the Tuatapere Hump Ridge Track Charitable Trust.', 'The Hump Ridge Track, also called the Tuatapere Hump Ridge Track, is a 60–62 km walking track partly within Fiordland National Park in New Zealand. It is run privately on behalf of the Tuatapere Hump Ridge Track Charitable Trust.'),
  ('en', 'jizerskohorske-buciny', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Jizera mountain beech is a national nature reserve, which was created on 16 August 1999 by the merger of the original seven national nature reserves Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantský cimmburi and Paličík by Decree No. 200 / 1999. In July [dated source] they became the first Czech natural monument included in the UNESCO World Heritage List.', 'The Jizera mountain beech forests (Jizerskohorské bučiny) form a national nature reserve created on 16 August 1999 by merging seven earlier reserves: Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantské cimbuří and Paličník. They became the first Czech natural site included on the UNESCO World Heritage List.'),
  ('en', 'junkerdal-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'The 682-square-kilometre park opened in [dated source].', 'A 682 km2 national park in Saltdal and Fauske, Nordland county, Norway, along the border with Sweden.'),
  ('en', 'junkerdal-national-park', 'tagline', 'tagline', null, 'REWRITE', 'The 682-square-kilometre park opened in [dated source].', 'A 682 km2 national park in Saltdal and Fauske, Nordland county, Norway, along the border with Sweden.'),
  ('en', 'kosterhavet-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Kosterhavet National Park is the first national marine park in Sweden, inaugurated in September [dated source]. It is part of the Skagerrak sea and is located in Strömstad and Tanum municipalities in Bohuslän, Västra Götaland County, Sweden. It consists of the sea and shores around the Koster Islands, excluding everything else on the islands. In the north, it borders the Norwegian marine park of Ytre Hvaler.', 'Kosterhavet National Park is Sweden''s first national marine park. It is part of the Skagerrak and lies in Strömstad and Tanum municipalities in Bohuslän, Västra Götaland County. It consists of the sea and shores around the Koster Islands, excluding the rest of the islands, and borders the Norwegian marine park of Ytre Hvaler to the north.'),
  ('en', 'kotychi-and-strofylia-wetlands-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'It was declared a national park in [dated source].', 'Protected wetlands and forest in Achaia and Ilia, with Kotychi Lake, the Strofylia Forest and Cape Araxos.'),
  ('en', 'kotychi-and-strofylia-wetlands-national-park', 'tagline', 'tagline', null, 'REWRITE', 'It was declared a national park in [dated source].', 'Protected wetlands and forest in Achaia and Ilia, with Kotychi Lake, the Strofylia Forest and Cape Araxos.'),
  ('en', 'langsua-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Langsua National Park was established in [dated source].', 'Langsua National Park protects 537.1 square kilometres in Innlandet county, Norway.'),
  ('en', 'langsua-national-park', 'tagline', 'tagline', null, 'REWRITE', 'Langsua National Park was established in [dated source].', 'Langsua National Park protects 537.1 square kilometres in Innlandet county, Norway.'),
  ('en', 'langsua-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Langsua National Park was established in [dated source]. The park consists of a total protected area of 537.1-square-kilometre . It is located in Innlandet county in Norway, and covers parts of the municipalities Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron and Nord-Fron.', 'Langsua National Park protects 537.1 square kilometres in Innlandet county, Norway, covering parts of the municipalities of Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron and Nord-Fron.'),
  ('en', 'les-deux-caps-blanc-nez-gris-nez', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source], its perimeter increases from eight to eighteen municipalities.', 'A Grand Site de France on the Opal Coast between Boulogne-sur-Mer and Calais, facing England.'),
  ('en', 'les-deux-caps-blanc-nez-gris-nez', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source], its perimeter increases from eight to eighteen municipalities.', 'A Grand Site de France on the Opal Coast between Boulogne-sur-Mer and Calais, facing England.'),
  ('en', 'liechtensteinklamm', 'seo_description', 'seo_description', null, 'CLEAR', 'Liechtensteinklamm is open daily from begin of May until 30 September [dated source] from 09:00 to 18:00 (last', ''),
  ('en', 'liechtensteinklamm', 'tagline', 'tagline', null, 'CLEAR', 'Liechtensteinklamm is open daily from begin of May until 30 September [dated source] from 09:00 to 18:00 (last', ''),
  ('en', 'liechtensteinklamm', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Liechtensteinklamm is open daily from begin of May until 30 September [dated source] from 09:00 to 18:00 (last admission at 18:00).', ''),
  ('en', 'lomsdal-visten-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Lomsdal–Visten National Park is a Norwegian national park that was established on 26 June [dated source]. The park consists of a total protected area of 1,102 square kilometres . It is located in Nordland county, Norway, and covers parts of Brønnøy Municipality, Vevelstad Municipality, Grane Municipality, and Vefsn Municipality.', 'Lomsdal–Visten National Park is a Norwegian national park with a protected area of 1,102 square kilometres. It lies in Nordland county and covers parts of Brønnøy, Vevelstad, Grane and Vefsn municipalities.'),
  ('en', 'loonse-en-drunense-duinen', 'seo_description', 'seo_description', null, 'REWRITE', 'It has been designated as a national park since [dated source].', 'A 35 km2 national park between Tilburg, Waalwijk and ''s-Hertogenbosch in the south of the Netherlands.'),
  ('en', 'loonse-en-drunense-duinen', 'tagline', 'tagline', null, 'REWRITE', 'It has been designated as a national park since [dated source].', 'A 35 km2 national park between Tilburg, Waalwijk and ''s-Hertogenbosch in the south of the Netherlands.'),
  ('en', 'lorship-bertiz-natural-park', 'seo_description', 'seo_description', null, 'REWRITE', 'The Natural Park Señorío de Bertiz (officially Bertizko Jaurerria Parke Naturala) [dated source] ha, is locate', 'Señorío de Bertiz is a natural park in the north-west of Navarre, Spain, declared in 1984.'),
  ('en', 'lorship-bertiz-natural-park', 'tagline', 'tagline', null, 'REWRITE', 'The Natural Park Señorío de Bertiz (officially Bertizko Jaurerria Parke Naturala) [dated source] ha, is locate', 'Señorío de Bertiz is a natural park in the north-west of Navarre, Spain, declared in 1984.'),
  ('en', 'marine-natural-park-of-picardy-and-opale-coast', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel marin des estuaires picards et de la mer d''Opale is a French marine natural park created in December [dated source]. It is located in front of the seven coastal rivers, from south to north, the Bresle, the Somme, the Authie, the Canche, the Liane, the Wimereux and the Slack. Its headquarters is located in Écault in the territory of Saint-Étienne-au-Mont, in the Pas-de-Calais.', 'The Parc naturel marin des estuaires picards et de la mer d''Opale is a French marine natural park off the mouths of seven coastal rivers: from south to north, the Bresle, the Somme, the Authie, the Canche, the Liane, the Wimereux and the Slack. Its headquarters are in Écault, in Saint-Étienne-au-Mont (Pas-de-Calais).'),
  ('en', 'marker-wadden-in-het-markermeer', 'seo_description', 'seo_description', null, 'REWRITE', 'The first island was inaugurated on 24 September [dated source].', 'The Marker Wadden is an artificial archipelago and nature reserve in the Markermeer lake, Netherlands.'),
  ('en', 'marker-wadden-in-het-markermeer', 'tagline', 'tagline', null, 'REWRITE', 'The first island was inaugurated on 24 September [dated source].', 'The Marker Wadden is an artificial archipelago and nature reserve in the Markermeer lake, Netherlands.'),
  ('en', 'mayotte-marine-natural-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Mayotte Marine Natural Park is a marine park surrounding Mayotte, a French overseas region. Mayotte is part of the Comoro Islands archipelago, which lies within the Mozambique Channel in the western Indian Ocean. Established in [dated source], the park covers the entirety of Mayotte''s territorial waters and exclusive economic zone. It is contiguous with the Glorioso Islands Marine Natural Park, which was established two years later.', 'The Mayotte Marine Natural Park surrounds Mayotte, a French overseas region in the Comoro Islands archipelago, in the Mozambique Channel of the western Indian Ocean. The park covers all of Mayotte''s territorial waters and exclusive economic zone and adjoins the Glorioso Islands Marine Natural Park.'),
  ('en', 'midden-delfland', 'seo_description', 'seo_description', null, 'REWRITE', 'It had a population of 19,355 in [dated source], and covers an area of 49.38 km2 of which 2.19 km2 is water.', 'Midden-Delfland is a municipality of 49.38 km2 in the Westland region of South Holland.'),
  ('en', 'midden-delfland', 'tagline', 'tagline', null, 'REWRITE', 'It had a population of 19,355 in [dated source], and covers an area of 49.38 km2 of which 2.19 km2 is water.', 'Midden-Delfland is a municipality of 49.38 km2 in the Westland region of South Holland.'),
  ('en', 'midden-delfland', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Midden-Delfland (Dutch: [ˌmɪdəˈdɛlflɑnt] ) is a municipality in the Westland region in the province of South Holland in the Netherlands. It had a population of 19,355 in [dated source], and covers an area of 49.38 km2 of which 2.19 km2 is water.', 'Midden-Delfland is a municipality in the Westland region of the province of South Holland in the Netherlands. It covers 49.38 km2, of which 2.19 km2 is water.'),
  ('en', 'millevaches-en-limousin', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Millevaches Regional Natural Park in Limousin is a French regional natural park created in [dated source], situated on the edge of three departments of the Nouvelle-Aquitaine region . It is, in chronological order, the second natural park of the Limousin regional territory; the first, the Perigord-Limousin park, dates from 1998. It is one of four NRPs in the new major region.', 'The Millevaches Regional Natural Park in Limousin is a French regional natural park on the edge of three departments of the Nouvelle-Aquitaine region. It is the second natural park in the Limousin area; the first, the Périgord-Limousin park, dates from 1998. It is one of four regional natural parks in the region.'),
  ('en', 'mont-ventoux', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Mont-Ventoux Regional Natural Park, in Provençal pargue dóu Ventours, is a regional natural park created by decree on 28 July [dated source]. It is the 55th regional nature park created in France, and the 9th in Provence-Alpes-Côte d''Azur.', 'The Mont-Ventoux Regional Natural Park (Provençal: pargue dóu Ventours) is the 55th regional nature park created in France and the 9th in Provence-Alpes-Côte d''Azur.'),
  ('en', 'mors-and-hanklit', 'seo_description', 'seo_description', null, 'REWRITE', 'It has an area of 367.3 km2 and as of 1 January [dated source], it had a population of 19,486.', 'Mors is a 367.3 km2 island in the Limfjord, Denmark, known for its diatomite (moler) deposits.'),
  ('en', 'mors-and-hanklit', 'tagline', 'tagline', null, 'REWRITE', 'It has an area of 367.3 km2 and as of 1 January [dated source], it had a population of 19,486.', 'Mors is a 367.3 km2 island in the Limfjord, Denmark, known for its diatomite (moler) deposits.'),
  ('en', 'mors-and-hanklit', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mors or Morsø is an island in the shallow sound called Limfjorden between Denmark''s Jutland peninsula and the North Jutlandic Island. It has an area of 367.3 km2 and as of 1 January [dated source], it had a population of 19,486. The main town on the island is called Nykøbing Mors. Geologically Mors is unique. Like the neighbouring island of Fur, it is known for its deposits of diatomite, locally known as ''moler'' .', 'Mors (Morsø) is an island in the Limfjord, the shallow sound between Denmark''s Jutland peninsula and the North Jutlandic Island. It has an area of 367.3 km2, and its main town is Nykøbing Mors. Geologically Mors is unique: like the neighbouring island of Fur, it is known for its deposits of diatomite, locally called ''moler''.'),
  ('en', 'morskie-oko', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Morskie Oko, or Eye of the Sea in English, is the largest and fourth-deepest lake in the Tatra Mountains, in southern Poland. It is located deep within the Tatra National Park in the Rybi Potok Valley, of the High Tatras mountain range at the base of the Mięguszowiecki Summits, in Lesser Poland Voivodeship. In [dated source], The Wall Street Journal recognized the lake as one of the five most beautiful lakes in the world.', 'Morskie Oko (''Eye of the Sea'') is the largest and fourth-deepest lake in the Tatra Mountains, in southern Poland. It lies deep within Tatra National Park in the Rybi Potok Valley of the High Tatras, at the foot of the Mięguszowiecki Summits, in Lesser Poland Voivodeship.'),
  ('en', 'nationaal-park-de-sallandse-heuvelrug', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source], the Dutch Government changed the status of the area to National Park.', 'Sallandse Heuvelrug is a national park in Overijssel, between the townships of Hellendoorn and Holten.'),
  ('en', 'nationaal-park-de-sallandse-heuvelrug', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source], the Dutch Government changed the status of the area to National Park.', 'Sallandse Heuvelrug is a national park in Overijssel, between the townships of Hellendoorn and Holten.'),
  ('en', 'nationaal-park-duinen-van-texel', 'seo_description', 'seo_description', null, 'REWRITE', 'The park covers approximately 43 km2 and attained national park status in [dated source].', 'Duinen van Texel National Park covers about 43 km2 of dunes and coastal plains on the island of Texel.'),
  ('en', 'nationaal-park-duinen-van-texel', 'tagline', 'tagline', null, 'REWRITE', 'The park covers approximately 43 km2 and attained national park status in [dated source].', 'Duinen van Texel National Park covers about 43 km2 of dunes and coastal plains on the island of Texel.'),
  ('en', 'national-park-drina', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Drina National Park is the fourth national park in Bosnia and Herzegovina, and the third in Republika Srpska. It was founded in [dated source]. The nearest town is Srebrenica. It is located on the other side of the Drina in relation to Tara National Park in Serbia.', 'Drina National Park is the fourth national park in Bosnia and Herzegovina and the third in Republika Srpska. The nearest town is Srebrenica. It lies on the opposite bank of the Drina from Tara National Park in Serbia.'),
  ('en', 'national-park-of-eastern-macedonia-and-thrace', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The National Park of Eastern Macedonia - Thrace was founded in [dated source] and included the already protected areas of D. Nestos, L. Vistonidas, L. Ismaridas and their wider area. The wetland complex of the National Park is one of the most important in Greece, due to its large area and its large biological, aesthetic, scientific, geomorphological and pedagogical value. The aim of the National Park is to effectively protect habitats and rare flora and fauna species that endemic and breed in the region.', 'The National Park of Eastern Macedonia and Thrace takes in the previously protected Nestos delta, Lake Vistonida, Lake Ismarida and their wider area. Its wetland complex is one of the most important in Greece because of its size and its great biological, aesthetic, scientific, geomorphological and educational value. The park aims to protect habitats and rare plant and animal species that are endemic to or breed in the region.'),
  ('en', 'national-park-of-messolonghi-aitoliko-lagoons', 'seo_description', 'seo_description', null, 'REWRITE', 'Created in [dated source], it encompasses the country''s largest lagoon complex.', 'The national park encompasses Greece''s largest lagoon complex, at the northwest end of the Gulf of Patras.'),
  ('en', 'national-park-of-messolonghi-aitoliko-lagoons', 'tagline', 'tagline', null, 'REWRITE', 'Created in [dated source], it encompasses the country''s largest lagoon complex.', 'The national park encompasses Greece''s largest lagoon complex, at the northwest end of the Gulf of Patras.'),
  ('en', 'nationalpark-mols-bjerge', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mols Bjerge National Park or Nationalpark Mols Bjerge is a Danish national park in the area known as Mols Bjerge in Syddjurs Municipality, Central Jutland, inaugurated on 29 August [dated source]. The protected area, measures 180 square kilometres in size. The Mols Hills, reaching a height of 137 metres, are centrally located in the park, and take up 2,500 ha. "More than half of all wild Danish plant species" can be found at Mols Bjerge.', 'Mols Bjerge National Park (Nationalpark Mols Bjerge) is a Danish national park in the Mols Bjerge area of Syddjurs Municipality, Central Jutland. The protected area measures 180 square kilometres. The Mols Hills, rising to 137 metres, lie at the centre of the park and take up 2,500 ha. More than half of all wild Danish plant species can be found at Mols Bjerge.'),
  ('en', 'nationalpark-thy', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Thy National Park is a national park area in Thy, Denmark, opened to the public on 22 August [dated source]. It is located in Northwest Jutland, along the coast from Hanstholm to Agger Tange and it spans 55 km north to south and 5–12 km east to west. The total area of the national park is 244 km2 .', 'Thy National Park is a national park in Thy, Denmark. It lies in Northwest Jutland along the coast from Hanstholm to Agger Tange, spanning 55 km from north to south and 5–12 km from east to west. The national park covers a total of 244 km2.'),
  ('en', 'natural-park-of-serra-d-irta', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Serra d''Irta Natural Park (Valencian: Parc Natural de la Serra d''Irta, Spanish: Parque Natural de la Sierra de Irta) is a natural park in Valencian Community), Southern Spain. It contains 7,744 hectares of land, as well as a shoreline of marine nature reserve of the adjacent Mediterranean Sea. It was declared a protected area in [dated source].', 'Serra d''Irta Natural Park (Valencian: Parc Natural de la Serra d''Irta; Spanish: Parque Natural de la Sierra de Irta) is a natural park in the Valencian Community, Spain. It covers 7,744 hectares of land, together with a marine nature reserve along the adjacent Mediterranean shoreline.'),
  ('en', 'naturpark-nissum-fjord', 'seo_description', 'seo_description', null, 'REWRITE', 'The Nature Park was approved by the Open Air Council on 12 December [dated source].', 'Nissum Fjord Nature Park covers 22,670 hectares around the fjord and is Denmark''s third-largest nature park.'),
  ('en', 'naturpark-nissum-fjord', 'tagline', 'tagline', null, 'REWRITE', 'The Nature Park was approved by the Open Air Council on 12 December [dated source].', 'Nissum Fjord Nature Park covers 22,670 hectares around the fjord and is Denmark''s third-largest nature park.'),
  ('en', 'naturpark-nissum-fjord', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Natural park Nissum Fjord was set up as a pilot project at the request of the Nissum Fjord Network in May [dated source]. The nature park extends over 22.670 hectares around Nissum Fjord and is the third largest natural park in Denmark. The Nature Park was approved by the Open Air Council on 12 December [dated source].', 'Nissum Fjord Nature Park extends over 22,670 hectares around Nissum Fjord and is the third-largest nature park in Denmark.'),
  ('en', 'north-pindos-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'North Pindos National Park is 230 km long and 70 km wide, founded in [dated source] and is considered one of the most important areas at national and European level. Also, the variety in rare species should be mentioned as almost all the large mammals of mainland Greece are hosted in the area. A total of 60 species of mammals, 166 species of birds, 30 species of reptiles, 14 species of amphibians and 17 species of fish are found in the park.', 'North Pindos National Park is 230 km long and 70 km wide and is considered one of the most important areas in Greece and in Europe. Almost all the large mammals of mainland Greece live here: in total 60 species of mammals, 166 of birds, 30 of reptiles, 14 of amphibians and 17 of fish are found in the park.'),
  ('en', 'ostmarka-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Østmarka National Park is a Norwegian national park created in [dated source]. It covers an area of 54 km2 in Østmarka, Oslo and Akershus Municipality Nordre Follo, Lørenskog, Røllen and Enebakk.', 'Østmarka National Park is a Norwegian national park covering 54 km2 of the Østmarka forest, in Oslo and in the Akershus municipalities of Nordre Follo, Lørenskog, Rælingen and Enebakk.'),
  ('en', 'paluma-range-national-park-qld', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'On National Parks Day [dated source], the Queensland State Government announced the addition of 6,510 hectares to the Paluma Range National Park.', ''),
  ('en', 'parc-naturel-regional-alpilles', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Alpilles Regional Nature Park is a French regional nature park created in [dated source], in Provence-Alpes-Côte d''Azur in the Bouches-du-Rhône department. It extends over the pre-alpine limestone massif of the Alpilles and its immediate surroundings .', 'The Alpilles Regional Nature Park is a French regional nature park in the Bouches-du-Rhône department of Provence-Alpes-Côte d''Azur. It covers the pre-alpine limestone massif of the Alpilles and its immediate surroundings.'),
  ('en', 'parc-naturel-regional-aubrac', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Aubrac Regional Natural Park is a French regional natural park created by decree on 23 May [dated source], whose perimeter occupies approximately 2,282 km2 spread over 64 communes of the three departments of Aveyron, Lozère and Cantal, around the plateau of the same name. It is the 53rd French Regional Natural Park.', 'The Aubrac Regional Natural Park is a French regional natural park covering about 2,282 km2 across 64 communes in the Aveyron, Lozère and Cantal departments, around the Aubrac plateau. It is the 53rd French regional natural park.'),
  ('en', 'parc-naturel-regional-de-guyane', 'seo_description', 'seo_description', null, 'REWRITE', 'The Guiana Regional Natural Park is a French regional natural park created in [dated source] in Guyane.', 'A regional natural park in French Guiana spread over six communes, from Iracoubo and Mana to Saint-Georges.'),
  ('en', 'parc-naturel-regional-de-guyane', 'tagline', 'tagline', null, 'REWRITE', 'The Guiana Regional Natural Park is a French regional natural park created in [dated source] in Guyane.', 'A regional natural park in French Guiana spread over six communes, from Iracoubo and Mana to Saint-Georges.'),
  ('en', 'parc-naturel-regional-de-guyane', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Guiana Regional Natural Park is a French regional natural park created in [dated source] in Guyane. It is divided into three terrestrial parts and two maritime portions, and covers the territory of six communes: Iracoubo, Mana, Ouanary, Roura, Saint-Georges and Sinnamary.', 'The Guiana Regional Natural Park is a French regional natural park in French Guiana. It is divided into three land areas and two marine areas and covers the territory of six communes: Iracoubo, Mana, Ouanary, Roura, Saint-Georges and Sinnamary.'),
  ('en', 'parc-naturel-regional-des-baronnies-provencales', 'seo_description', 'seo_description', null, 'REWRITE', 'This regional nature park was established on January 26, [dated source].', 'A regional nature park on an alpine massif between the Drôme and Hautes-Alpes, covering 104 municipalities.'),
  ('en', 'parc-naturel-regional-des-baronnies-provencales', 'tagline', 'tagline', null, 'REWRITE', 'This regional nature park was established on January 26, [dated source].', 'A regional nature park on an alpine massif between the Drôme and Hautes-Alpes, covering 104 municipalities.'),
  ('en', 'parc-naturel-regional-des-baronnies-provencales', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The regional nature park of the Provencal Baronnies extends over an alpine massif between the departments of Drôme and Hautes-Alpes in the south-east of France. This regional nature park was established on January 26, [dated source]. It covers 104 municipalities in whole or in part.', 'The Baronnies Provençales Regional Nature Park extends over an alpine massif between the Drôme and Hautes-Alpes departments in south-east France. It covers 104 municipalities in whole or in part.'),
  ('en', 'parc-naturel-regional-des-prealpes-d-azur', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel régional des Préalpes d''Azur is a French regional natural park created on 30 March [dated source] and located in the Alpes-Maritimes department, in the Provence-Alpes-Côte d''Azur region. It is precisely located in the Prealps of Grasse, between the valleys of Siagne, Wolf, Cagne, Esteron and Var.', 'The Parc naturel régional des Préalpes d''Azur is a French regional natural park in the Alpes-Maritimes department of Provence-Alpes-Côte d''Azur. It lies in the Prealps of Grasse, between the valleys of the Siagne, Loup, Cagne, Estéron and Var.'),
  ('en', 'parc-naturel-regional-medoc', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Médoc Regional Natural Park is a regional natural park located in the Gironde department, in the Nouvelle-Aquitaine region, classified by decree of May 24, [dated source]. It becomes France''s 54th regional natural park and covers part of the natural region of Médoc.', 'The Médoc Regional Natural Park lies in the Gironde department of the Nouvelle-Aquitaine region. It is France''s 54th regional natural park and covers part of the Médoc natural region.'),
  ('en', 'parc-naturel-regional-oisepays-de-france', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Oise-Pays de France regional nature park, created on 13 January [dated source] by decree of the Prime Minister, covers 70 communes in the departments of Oise and Val-d''Oise. It is one of the few parks spread over two administrative regions, the fourth PNR of the Hauts de France and the fourth in Île-de-France.', 'The Oise-Pays de France Regional Nature Park covers 70 communes in the Oise and Val-d''Oise departments. It is one of the few parks spread over two administrative regions: the fourth regional natural park of Hauts-de-France and the fourth in Île-de-France.'),
  ('en', 'parco-dei-monti-sicani', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sicani Mountains park was a regional natural park of Sicily established on 19 December [dated source] and suppressed in July [dated source]. It included 12 municipalities in the territories of the free municipal consortium of Agrigento and the metropolitan city of Palermo, Sicily.', 'The Sicani Mountains park was a regional natural park of Sicily that has since been abolished. It included 12 municipalities in the free municipal consortium of Agrigento and the metropolitan city of Palermo.'),
  ('en', 'parco-naturale-regionale-bosco-incoronata', 'seo_description', 'seo_description', null, 'REWRITE', 'The Regional Natural Park Bosco Incoronata is a protected natural area established in [dated source] along the', 'A protected natural area along the river Cervaro, about 12 kilometres from Foggia in Apulia.'),
  ('en', 'parco-naturale-regionale-bosco-incoronata', 'tagline', 'tagline', null, 'REWRITE', 'The Regional Natural Park Bosco Incoronata is a protected natural area established in [dated source] along the', 'A protected natural area along the river Cervaro, about 12 kilometres from Foggia in Apulia.'),
  ('en', 'parco-naturale-regionale-bosco-incoronata', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Regional Natural Park Bosco Incoronata is a protected natural area established in [dated source] along the river Cervaro about 12 kilometers from the city of Foggia, in the heart of the Apulia Tablet.', 'The Bosco Incoronata Regional Natural Park is a protected natural area along the river Cervaro, about 12 kilometres from Foggia, in the heart of the Tavoliere plain of Apulia.'),
  ('en', 'parco-naturale-regionale-del-vulture', 'seo_description', 'seo_description', null, 'REWRITE', 'The Vulture Regional Natural Park is a protected natural area established in November [dated source]. This reg', 'A protected natural area around the Vulture, including part of Melfi, in the Province of Potenza.'),
  ('en', 'parco-naturale-regionale-del-vulture', 'tagline', 'tagline', null, 'REWRITE', 'The Vulture Regional Natural Park is a protected natural area established in November [dated source]. This reg', 'A protected natural area around the Vulture, including part of Melfi, in the Province of Potenza.'),
  ('en', 'parco-naturale-regionale-del-vulture', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Vulture Regional Natural Park is a protected natural area established in November [dated source]. This regional park includes the Vulture area as well as part of the municipal territories of Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte and San Fele, all belonging to the Province of Potenza.', 'The Vulture Regional Natural Park is a protected natural area that includes the Vulture area and parts of the municipalities of Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte and San Fele, all in the Province of Potenza.'),
  ('en', 'parco-naturale-regionale-terra-delle-gravine', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Terra delle Gravine natural park is a protected natural area established in Puglia in [dated source]. The area covers the provinces of Brindisi and Taranto, in the Murge area.', 'The Terra delle Gravine natural park is a protected natural area in Apulia, covering parts of the provinces of Brindisi and Taranto in the Murge area.'),
  ('en', 'ponga-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Natural Park of Ponta is a Spanish protected natural space, situated in the central area of the Cantábrica range with a protected area of 20533 ha, and most of them are the town council of Ponta. It was intended to be first included in the Reds Park at the end of the period and its name as a natural park was later and with its own identity. It was declared by law 4 / [dated source].', 'Ponga Natural Park is a Spanish protected natural space in the central area of the Cantábrica range, with a protected area of 20,533 ha, most of it in the municipality of Ponga.'),
  ('en', 'reinheimen-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reinheimen National Park is a national park in Norway that was established in [dated source]. The park consists of a 1,969-square-kilometre continuous protected mountain area. It is located in Møre og Romsdal and Innlandet counties in Norway. The park includes parts of the municipalities of Lesja, Skjåk, Vågå, Lom, Fjord, and Rauma. The park consists of much of the Tafjordfjella mountain range as well as the reindeer habitat in the northern part of the Ottadalen valley.', 'Reinheimen National Park is a national park in Norway with a continuous protected mountain area of 1,969 square kilometres in Møre og Romsdal and Innlandet counties. It includes parts of the municipalities of Lesja, Skjåk, Vågå, Lom, Fjord and Rauma, much of the Tafjordfjella mountain range and the reindeer habitat in the northern part of the Ottadalen valley.'),
  ('en', 'reynisdrangar', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source] Reynisfjara [ˈreiːnɪsˌfjaːra] was rated the sixth best beach in the world.', 'Basalt sea stacks below Reynisfjall near Vík í Mýrdal in southern Iceland, framed by a black sand beach.'),
  ('en', 'reynisdrangar', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source] Reynisfjara [ˈreiːnɪsˌfjaːra] was rated the sixth best beach in the world.', 'Basalt sea stacks below Reynisfjall near Vík í Mýrdal in southern Iceland, framed by a black sand beach.'),
  ('en', 'reynisfjara', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reynisfjara is a popular black sand beach in southern Iceland near the town of Vík í Mýrdal. It is part of the Katla UNESCO Global Geopark on privately owned land. In February [dated source], following weeks of strong waves and easterly winds, part of the iconic basalt columns collapsed along with significant erosion of the beach. With the return of westerly winds in March, Reynisfjara is expected to return to its familiar appearance.', 'Reynisfjara is a popular black sand beach in southern Iceland near the town of Vík í Mýrdal. It is part of the Katla UNESCO Global Geopark, on privately owned land.'),
  ('en', 'rhine-falls', 'seo_description', 'seo_description', null, 'REWRITE', '13 November [dated source] to 3 January [dated source]: The illumination of the Schloss Laufen on the Rhine Fa', 'Europe''s largest waterfall, flanked by Laufen and Wörth castles and seen from the SBB railway bridge.'),
  ('en', 'rhine-falls', 'tagline', 'tagline', null, 'REWRITE', '13 November [dated source] to 3 January [dated source]: The illumination of the Schloss Laufen on the Rhine Fa', 'Europe''s largest waterfall, flanked by Laufen and Wörth castles and seen from the SBB railway bridge.'),
  ('en', 'rohkunborri-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Rohkunborri National Park is a national park in Troms county, Norway, that was established in [dated source]. The park consists of a 571-square-kilometre protected area, and is located in Bardu Municipality along the border with Sweden, about 30 kilometres southeast of the village of Setermoen and about 50 kilometres northeast of the town of Narvik.', 'Rohkunborri National Park is a national park in Troms county, Norway, with a protected area of 571 square kilometres. It lies in Bardu Municipality along the border with Sweden, about 30 kilometres southeast of the village of Setermoen and about 50 kilometres northeast of the town of Narvik.'),
  ('en', 'rosalia-kogelberg-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'As part of the project “Barrier-free nature experience Rosalia-Kogelberg”, a hiking and nature experience for all senses was created between [dated source] and [dated source]. The project included, among other things, the conception and construction of a total of eleven barrier-free experience and rest stations along the so-called Eulenweg or along the “Tour Teichwiesen”.', 'As part of the project ''Barrier-free nature experience Rosalia-Kogelberg'', a hiking and nature trail for all the senses was created. The project included the design and construction of eleven barrier-free experience and rest stations along the Eulenweg and the Tour Teichwiesen.'),
  ('en', 'saimaa-unesco-global-geopark', 'seo_description', 'seo_description', null, 'REWRITE', 'The area received UNESCO Global Geopark status in [dated source].', 'A UNESCO Global Geopark with 65 geo-sites around Lake Saimaa, Finland''s largest lake.'),
  ('en', 'saimaa-unesco-global-geopark', 'tagline', 'tagline', null, 'REWRITE', 'The area received UNESCO Global Geopark status in [dated source].', 'A UNESCO Global Geopark with 65 geo-sites around Lake Saimaa, Finland''s largest lake.'),
  ('en', 'sainte-baume-regional-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sainte-Baume Regional Nature Park is a regional nature park created by decree on December 20, [dated source], with a perimeter of approximately 84,367 ha distributed between the two departments of Bouches-du-Rhône and Var, around the massif of the same name. It is the 52nd French Regional Natural Park.', 'The Sainte-Baume Regional Nature Park covers about 84,367 ha across the Bouches-du-Rhône and Var departments, around the massif of the same name. It is the 52nd French regional natural park.'),
  ('en', 'salpausselka-unesco-global-geopark', 'seo_description', 'seo_description', null, 'REWRITE', 'Salpausselkä Geopark was accepted on 13 April [dated source].', 'Salpausselkä Geopark spans Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki in Finland.'),
  ('en', 'salpausselka-unesco-global-geopark', 'tagline', 'tagline', null, 'REWRITE', 'Salpausselkä Geopark was accepted on 13 April [dated source].', 'Salpausselkä Geopark spans Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki in Finland.'),
  ('en', 'salpausselka-unesco-global-geopark', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Salpausselkä Geopark was accepted on 13 April [dated source]. Salpausselkä Geopark consists of the municipalities of Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki. The area is located for example in Päijänte National Park, the Tiirismaa region, Kelvenne, Pulkkilanharju, Paistjarvi Reserve, Vakumuori, Water Division Nature Park, Koreakoivu and Kutajärvi.', 'Salpausselkä Geopark consists of the municipalities of Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki. Its sites include Päijänte National Park, the Tiirismaa area, Kelvenne, Pulkkilanharju, the Paistjärvi reserve, Vakumuori, the Water Division Nature Park, Koreakoivu and Kutajärvi.'),
  ('en', 'salzburger-lungau-and-karntner-nockberge-biosphere', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Salzburger Lungau and the adjacent Carinthian Nockberge were awarded as a Biosphere Park by UNESCO in July [dated source]. It covers the entire Salzburg district of Tamsweg (Lungau) and adjacent areas of the Nockberge in Carinthia. This makes the area bordering the federal states of Salzburg and Carinthia a “model region for sustainable development”.', 'Salzburger Lungau and the adjacent Carinthian Nockberge have been recognised by UNESCO as a Biosphere Park. It covers the whole Salzburg district of Tamsweg (Lungau) and neighbouring parts of the Nockberge in Carinthia, making this border area of Salzburg and Carinthia a ''model region for sustainable development''.'),
  ('en', 'sequoia-park-of-monte-cabezon', 'seo_description', 'seo_description', null, 'REWRITE', 'The following are a "protected natural space" of Cantabria, declared a Natural Monument by Decree 41 / [dated ', 'The Sequoia Park of Monte Cabezón is a Natural Monument and protected natural space of Cantabria.'),
  ('en', 'sequoia-park-of-monte-cabezon', 'tagline', 'tagline', null, 'REWRITE', 'The following are a "protected natural space" of Cantabria, declared a Natural Monument by Decree 41 / [dated ', 'The Sequoia Park of Monte Cabezón is a Natural Monument and protected natural space of Cantabria.'),
  ('en', 'sequoia-park-of-monte-cabezon', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The following are a "protected natural space" of Cantabria, declared a Natural Monument by Decree 41 / [dated source] of the Government of Cantabria and included in the Network of Natural Space Protected by Cantabria Act 4 / [dated source] of 19 May.)', 'The Sequoia Park of Monte Cabezón is a protected natural space of Cantabria, declared a Natural Monument by the Government of Cantabria and included in Cantabria''s network of protected natural spaces.'),
  ('en', 'serra-da-encina-da-lastra-natural-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sierra de la Lasse Natural Park () () () () is a Spanish protected natural space situated in the north-eastern province of Orense, in the municipality of Rubiana, Valdeoras, and was declared a Natural Park in [dated source] by the Galicia Board. It has an area of 3151.67 ha and an average height of 684 m. It''s a limestone valley with pronounced slopes and cantils with a Mediterranean forest. A particularly important area of public interest, especially for its rapist bird populations, among them the presence of the Royal Eagle and the Pereer Falcon. The abundance of caves - referred to here as shovels - leads to the existence of numerous colonies of bats, the most important of Galicia. A further point of interest lies in the presence of Mediterranean-type grazing areas characteristic of rocky mountain areas.)', 'Serra da Enciña da Lastra Natural Park is a Spanish protected natural space in the north-east of the province of Ourense, in the municipality of Rubiá (Valdeoras), declared a Natural Park by the Galician government. It covers 3,151.67 ha with an average altitude of 684 m: a limestone valley with steep slopes, cliffs and Mediterranean woodland. It is especially important for birds of prey, including the golden eagle and the peregrine falcon. Its many caves shelter numerous bat colonies, the most important in Galicia, and it also has Mediterranean-type grazing land typical of rocky mountain areas.'),
  ('en', 'serra-de-tramuntana', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Serra de Tramuntana (Balearic Catalan: [ˈsɛrə ðə tɾəmunˈtanə]) is a mountain range running southwest–northeast which forms the northern backbone of the Spanish island of Mallorca. It is also the name given to the comarca of the same area. On 27 June [dated source], the Tramuntana Range was awarded World Heritage Status by UNESCO as an area of great physical and cultural significance.', 'The Serra de Tramuntana is a mountain range running southwest–northeast that forms the northern backbone of the Spanish island of Mallorca; it is also the name of the comarca covering the same area. The Tramuntana Range has UNESCO World Heritage status, recognised as an area of great physical and cultural significance.'),
  ('en', 'sheskinmore-nature-reserve', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sheskinmore Nature Reserve Location: GPS: Latitude: 54.794006 Longitude: -8.463635 Area : Sheskinmore refers to a large area of sand dunes, lake and marsh that lies between Kiltooris and Ballinreavy Strand, north west of Ardara, Co. Donegal. The area is designated as a Special Area of Conservation, a Special Protection Area and a Wildfowl Sanctuary. The area is easily accessed from the gate at Mullyvea opposite Kiltooris Lough. Is ceantar mór dumcha, locha agus seascainn é Seascann Mór atá idir Cill Dorais agus Trá Bhaile an Riabhaigh ar thaobh thiar thuaidh d’Ard Ratha, Co. Dhún na nGall. Tá an ceantar ainmnithe mar Cheantar Speisialta Caomhnaithe, mar Cheantar Cosanta Speisialta agus mar Thearmann Éanlaithe. Tá sé furasta dul isteach ann tríd an geata ag Mullach Bheitheach os coinne Loch Chill Dorais. Habitats The area is mostly a fixed sand dune system, which includes machair grassland, dune slacks, Sheskinmore lough and the surrounding marsh, fen and reedbed. There is some oak and hazel scrub with heath on the drier northern slopes behind the lough and there is also coastal heath on the Carrickalagh headland. Sescenn Mór literally means “big marsh” and the marshy plain contains much of the areas’ interesting flora and fauna. South and west of the flat marshy plain there are sandy machair grasslands which evolve into high undulating sand dunes along Trawmore Strand and Ballinreavy Strand. Gnáthóga Is córas duimhche seasta an ceantar seo den chuid is mó ina bhfuil talamh féarach, machaire, dumhcha, Loch an tSeascainn Mhóir, machaire moing agus sraith ghiolcach thart air. Tá crainn dharach agus scrobarnach coil maraoin le fraoch ar na fánaí tirime ar an taobh thuaidh den loch agus tá fraoch cósta ar cheann tire Charraig Adhlactha. Ciallaíonn Seascann Mór bogach nó corrach mór agus ta fásra agus ainmhíthe suimiúla le fail ar chuid mhaith den mhachaire corrach seo. Ar an taobh theas agus thiar den mhachaire tá talaimh féir gainimh a éiríonn ansin i ndumhcha droimnigh arda le taobh trá na Trá Móire agus Trá Bhaile an Riabhaigh Birds A visit at any time of year is always interesting for birdlife. During the winter a small flock of Greensland White Fronted Geese feed undisturbed here. Chough and Twite also feed here in Winter. Brent Goose, Whooper Swan, Wigeon, Tufted Duck, Goldeneye and Golden Plover are other winter visitors. Lapwing, Mallard, Teal, Snipe and Mute Swan are found all year round as are Linnet, Skylark, Meadow pipit, Stonechat and Reed Bunting. Summer visitors include the Grasshopper, Sedge and Willow Warblers and Wheatear, Swallow and Cuckoo. Birds of prey species use this vast open undisturbed site to hunt. Ein Is fiú go mór cuairt a thabhairt anseo ag am ar bith den bhliain chun an éanlaith shuimiúil a fheiceáil. I rith an gheimhridgh bíonn scata Géanna le Brollaigh Bhána ón Ghraonlainn a chothú ann. Bionn an Cág Deargchosach agus an Ghleoiseach Shléibhe ann as gheimhreadh. Is cuairteoirí geimhridgh eile iad an Ghé Dhubh, an Eala Ghlórach, an Lacha rua, an Lacha Dhubh, an Feadóg Shléibhe agus Feadóg na Súile Óire. Chítear an Pilibín, an Mallard, an Phraslacha, an Naoscach, an Eala Bhalbh ann I rith nab liana chomh maith leis an Ghleoiseach, an Fhuiseog, an Riabhógmhóna, an Chloch Dearg agus an Ghealóg Dhúcheannach. I rith an tsamhraidh bionn an Dreoilin Teaspaigh, an Chíb, an Ceolaire Sailí, an Chlochrán, an Fhainleog agus an Chuach le feiceáil ann. Úsáideann éin chreiche an láithreán leathan oscaillte seo mar thalamh seilge. Plants The fixed dune and machair are managed to enhance their species richness. Cattle graze extensively during the winter months only. Orchid species include the Marsh Helleborine, Bee Orchid, Frog Orchid and the rare Irish Orchid. There is a succession of colour throughout the summer months in the dunes and on the marsh, from yellows and whites in spring through to the pinks and purples of the late summer. Rarieties recorded in the area include the aquatic slender naiad and pipewort, the tiny petalwort, also quillwort, hoary whitlow grass and many stonewort species. Plandaí Riaraítear na dumhcha seasta agus an machaire chun siabhreas na ngnéithe a mhéadu. Bíonn eallach ag iníorgo tréan anseo i rith míonna an gheimhridh amháin. I measc an ngnéithe magairlíne tá Cuacihín Corraigh, Magairlín na mBeach, Magairlín an Ioscáin agus Magairlín Éireannach atá neamhchoitianta. Bíonn athraithe datha trí mhíonna an t-samhraidh sna dumhcha agus ar an machaire ó dhath buí agus bán an earraigh go dathanna bándearga agus corcra dheireadh an t-samhraidh. I measc na ngnéithe neamhchoitianta a rinneadh cuntas orthu sa cheantar seo tá nimfigh uisce, píbín uisce, tursarraing chleite, bosán anagair agus tursarraing chloiche. Animals Rabbits, badgers and foxes are the most common mammals recorded at Sheskinmore. Otter have been seen in the lough. Frog and newt breed in and around the dune slacks and the common lizard breeds on the drier slopes. The protected tiny marsh snail species Vertigo geyeri is found in the fen habitat west of the lough. The area is also noteworthy for the variety of butterflies and dragonflies that breed here. Marsh fritillary and dingy skipper both breed at Sheskinmore along with 18 other butterfly species. Sheskinmore lough and associated wetlands is the most species rich site in Donegal for dragonflies and damselflies. Fifteen species have been recorded, the most interesting being the Black-tailed Skimmer and the small Blue tip. 2 Ainmhithe Is iad coiníní, broic agus sionnaigh na siní is coitianta ar an t-Seascann Mór. Chonacthas dobharchúnna sa loch. Bíonn an frog agus an t-earc luachra ag síolrú thart ar na dumhcha agus an t-earc coitianta ag síolrú ar na fánaí tirime. Faightear seilidí beaga corraigh. Vertigo geyeri atá cosanta sa ghnáthóg moinge taobh thiar den loch.Tá cáil ar an cheantar seo as ucht ilghnéitheachta na bhfeileacán agus na snatháidí móra a shíolraíonn anseo. Bíonn Fritileáin corraigh agus Preabairí modartha ag síolrú ar an SEascann Mór maraon le ocht ngné déag d’fheileacán. Bíonn níos mó gnéithe de shnatháidí móra agus cuileoga daimsil le fail I gceantar Loch an t-Seascainn Mhóir agus na talaimh fliucha thart air ná in áit ar bith eile i gCo. Dhún na nGall. Rinneadh cuntas oifigiúil ar cúig ghné déag díobh agus Snatháid an Eireaball Dhuibh agus Snatháid Bheag an Bhairr Ghoirm ar na cinn is suimiúla. Management The property is managed by NPWS to maximise its biodiversity. The area is rich in marsh and dune plants and supports a wide variety of invertebrates and birds. The cereal plot at the Mullyvea entrance was first planted in [dated source] to feed finches and buntings during the winter months. Another plot is planned for Sandfield. The site is winter grazed to encourage floral diversity and cow pats are also a source of food for foraging chough. Stocking rates are periodically reviewed and horses may at times be grazed on the site. Various methods have been tried to control bracken. A sluice is in place to control water levels at the lough in order to protect the slender naiad population. In [dated source] McGlinchey’s house at Sandfield was fully restored and is now used as a field studies centre. Bainistíocht Riaraíonn an NPWS an eastát se chun uasmhéid éagsúlacht bheatha a fháil. Is ceantar saibhir é le plandaí seascainn agus dumhcha a chothaíonn éagsúlacht leathan éan agus ainmhíthe gan cnámh droma. Cuireadh arbhar don chéad uair I [dated source] ag bealach insteach ag Mullach Bheitheach chun na gealóga a bheathú i rith an gheimhridh.Tá plean do phlota eile arbhair ag Achadh an Ghainimh. Cuirtear eallach ag iníor ar an láitrhreán sa gheimhreadh chun cuidiú leis an éagsúlacht bláthanna agus is foinse bia an cac bó do na cáig dhearg-chosacha. Coinnítear súil ar an stoc ó am go ham agus b’fheider go ligtar do chapaill a bheith ar fhéar anseo chomh maith. Úsáideadh dóigheanna éagsúla chun smacht a chur ar an raithneach. Cuireadh loc-chomhla ann chun leibhéil an uisce a chosaint. I [dated source] coíríodh Teach Mhic Loinsigh in Achadh an Ghainimh agus tá sé in úsáid mar ionad staidéir amuigh faoin aer. Access & Safety There are three signed access points. The main entrance is at the Mullyvea gate opposite Kiltooris Lough. There is access from the east side at both Murveagh and Sandfield of the R261. Walkers should be cautious of grazing animals between October and May and dogs should be kept on a lead and under control at all times. Some of the land within the site is still privately owned so be careful to close gates and not to damage walls or fences. Appropriate walking clothing and a map and compass are recommended. Any damaging activities should be reported to NPWS at Gleanveagh National Park 074 -9137090 or NPWS at Ballinafad, Co. Sligo, 071 9666700 Bealach Isteach agus Sábháilteacht Tá trí bhealach isteach le comharthaí. Tá an príomhbhealach isteach ag geata an Mhullaigh Bheitheach os coinne Loch Chill Dorais. Tá bealach isteach ón taobh thoir ag Muirbheitheach Bheitheach agus Achadh an Ghainimh ón R261. Ba choir do shiúlóirí o bheith cúramach roimh ainmhíthe ar fhéar ó Dheireadh Fómhair go Bealtaine agus ba cheart madaí a choinneáil ar éill agus faoi smacht an t-am uilig. Ná dean dearmad na geataí a dhruid ná dochar a dhéanamh do bhallaí agus do fhálta.Moltar do shiúlóirí éadai foirstineacha a chaítheamh agus léarscáil agus compass a thabhairt leo. Má bhíonn imeachtaí a chuisíonn dochar ba choir fios a chur ar an tSeirbhís Páirceanna Náisiúnta agus Fiadhúlra I nGleann Bheitheach 074-9137090 nó ag Baile an Atha Fada, Co. Shligigh 071- 9666700 Established: Ownership: State-owned', 'Sheskinmore is a large area of sand dunes, lake and marsh between Kiltooris and Ballinreavy Strand, north-west of Ardara, Co. Donegal. It is a Special Area of Conservation, a Special Protection Area and a Wildfowl Sanctuary, and is easily reached from the gate at Mullyvea opposite Kiltooris Lough. The site is mostly a fixed dune system with machair grassland, dune slacks, Sheskinmore Lough and its surrounding marsh, fen and reedbed. In winter a small flock of white-fronted geese feeds here, along with chough and twite; orchids include the marsh helleborine, bee orchid and the rare Irish orchid. The reserve is managed by NPWS and grazed in winter to encourage floral diversity. Walkers should take care around grazing animals between October and May, keep dogs on a lead and close gates, as some of the land is privately owned.'),
  ('en', 'sila-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sila National Park (Italian: Parco nazionale della Sila) is an Italian national park in Calabria, located on the Sila Plateau. It was established in 1997 and covers about 74,000 hectares (180,000 acres). Its highest mountains are Mt. Botte Donato (1,928 m), in Sila Grande, and Mt. Gariglione (1,764 m) in Sila Piccola. The park was established with the Regional Decree of 14 November [dated source] and includes its own management agency. The park includes the territories formerly part of the Calabria National Park (1968), and protects areas of great environmental interest in Sila Piccola, Sila Grande and Sila Greca, for a total of 736.95 square kilometres (284.54 sq mi), in 21 municipalities (comuni) and 6 "mountain communities" (comunità montane) across the three Calabrian provinces of Catanzaro, Cosenza and Crotone.', 'Sila National Park (Italian: Parco nazionale della Sila) is an Italian national park in Calabria, on the Sila Plateau. It was established in 1997 and covers about 74,000 hectares. Its highest mountains are Mt. Botte Donato (1,928 m) in Sila Grande and Mt. Gariglione (1,764 m) in Sila Piccola. The park takes in land formerly part of the Calabria National Park (1968) and protects areas of great environmental interest in Sila Piccola, Sila Grande and Sila Greca, in 21 municipalities across the provinces of Catanzaro, Cosenza and Crotone.'),
  ('en', 'sjunkhatten-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Sjunkhatten National Park was established in [dated source] in Nordland county, Norway.', 'A 417.5 km2 national park on a peninsula between Sørfolda and Saltfjorden in Nordland, Norway.'),
  ('en', 'sjunkhatten-national-park', 'tagline', 'tagline', null, 'REWRITE', 'Sjunkhatten National Park was established in [dated source] in Nordland county, Norway.', 'A 417.5 km2 national park on a peninsula between Sørfolda and Saltfjorden in Nordland, Norway.'),
  ('en', 'sjunkhatten-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sjunkhatten National Park was established in [dated source] in Nordland county, Norway. The park consists of a 417.5-square-kilometre continuously protected area, including 39.8-square-kilometre sea area in Bodø Municipality, Fauske Municipality, and Sørfold Municipality. The park is located on a peninsula between the Sørfolda fjord and Saltfjorden, including glacier-formed landscape, caves and water systems, fjords, the large lake Heggmovatnet, rare animal species, and cultural heritage.', 'Sjunkhatten National Park lies in Nordland county, Norway. It is a continuous protected area of 417.5 square kilometres, including 39.8 square kilometres of sea, in Bodø, Fauske and Sørfold municipalities. The park sits on a peninsula between the Sørfolda fjord and Saltfjorden, with glacier-formed landscape, caves and water systems, fjords, the large lake Heggmovatnet, rare animal species and cultural heritage.'),
  ('en', 'south-harz-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The South Harz Nature Park (German: Naturpark Südharz) is located in the county of Nordhausen in north Thuringia, Germany. The act designating this nature park in the Harz Mountains came into force on 31 December [dated source] and thus founded the fifth nature park in Thuringia. It has an area of 267 km². The park is managed by the South Harz Tourist Association (Südharzer Tourismusverband e.V.) in conjunction with the Kyffhäuser Nature Park.', 'The South Harz Nature Park (German: Naturpark Südharz) lies in the district of Nordhausen in northern Thuringia, Germany. It is the fifth nature park in Thuringia and covers 267 km² of the Harz Mountains. The park is managed by the South Harz Tourist Association (Südharzer Tourismusverband e.V.) together with the Kyffhäuser Nature Park.'),
  ('en', 'sparbach-nature-park', 'seo_description', 'seo_description', null, 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('en', 'sparbach-nature-park', 'tagline', 'tagline', null, 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('en', 'sparbach-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses Ereignis wurde in einem Film festgehalten.', ''),
  ('en', 'sternberg-lake-land-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sternberger Lakeland Nature Park is a development area for agriculture and tourism (Landesraumentwicklungprogramm M-V [dated source]), not for industrial plants. The Expert Landscape Framework Plan (GLRP) identifies the entire area as a special area for the biotope network, which has a high to very high importance for the landscape.', 'The Sternberg Lake Land Nature Park is designated for agricultural and tourism development, not for industrial plants. The expert landscape framework plan (GLRP) classes the entire area as a special area for the biotope network, of high to very high importance for the landscape.'),
  ('en', 'tomorr-mountain-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Tomorr Mountain National Park is a national park founded in 1956 that lies in southern Albania, nestled in the central and higher portions of the Tomorr massif, spanning an area of 261.06 km2 since [dated source], and expanded to include its quarry areas since [dated source]. The park covers a territory of 26,106 ha . The area falls within the Berat County and only 1,278 ha inside the Elbasan County. The park was established in 1956 and is considered one of the most important protected areas for the maintenance of mountainous biodiversity and ecosystem integrity at the national level. The park has been recognised as an Important Plant Area of international importance by Plantlife.', 'Tomorr Mountain National Park, founded in 1956, lies in southern Albania in the central and higher parts of the Tomorr massif and covers 261.06 km2 (26,106 ha). Most of it is in Berat County, with only 1,278 ha in Elbasan County. It is considered one of the most important protected areas for mountain biodiversity and ecosystem integrity in Albania and is recognised by Plantlife as an Important Plant Area of international importance.'),
  ('en', 'tongariro-northern-circuit', 'seo_description', 'seo_description', null, 'REWRITE', 'Approximately 2,500 hikers completed the walk in the [dated source]/22 season.', 'A three- to four-day Great Walk through Tongariro National Park, circling Mount Ngauruhoe over about 50 km.'),
  ('en', 'tongariro-northern-circuit', 'tagline', 'tagline', null, 'REWRITE', 'Approximately 2,500 hikers completed the walk in the [dated source]/22 season.', 'A three- to four-day Great Walk through Tongariro National Park, circling Mount Ngauruhoe over about 50 km.'),
  ('en', 'una-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Una National Park was established on 29 May [dated source] around the rivers Upper Una River, Krka and the Unac. It is Bosnia and Herzegovina''s largest national park. The main purpose of the park is to protect the unspoiled Una river and its tributaries Krka and Unac, which run through it.', 'Una National Park lies around the Upper Una River and its tributaries the Krka and the Unac. It is the largest national park in Bosnia and Herzegovina, and its main purpose is to protect the unspoiled Una and these tributaries, which run through it.'),
  ('en', 'wienerwald-biosphere-reserve', 'seo_description', 'seo_description', null, 'REWRITE', 'The Wienerwald was designated as a Biosphere Reserve in [dated source] by UNESCO. This standing protects the g', 'The Wienerwald is a UNESCO Biosphere Reserve of wooded hills, meadows, orchards, vineyards and dry grasslands in Lower Austria and Vienna.'),
  ('en', 'wienerwald-biosphere-reserve', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Wienerwald was designated as a Biosphere Reserve in [dated source] by UNESCO. This standing protects the great variety of natural and cultural elements that make this region so unique and valuable. Wide range of wooded hills alternates with vast meadows, pastures and fruit orchards as well as vineyards and dry grasslands - the products from centuries of cultivation by humans. Four Nature Parks and the Viennese Lainzer Tiergarten, an extensive game park, are among the 15 nature preserves in this region.

BRs are ecosystems, recognized on the basis of uniform, internationally agreed criteria, where models of sustainable use of the biosphere are being developed, tested and implemented. Together with local partners and authorities, the states of Lower Austria and Vienna develope a model region for sustainability to address the challenges of the 21st century. Present and future generations can benefit from.', 'The Wienerwald has been designated a Biosphere Reserve by UNESCO. This status protects the great variety of natural and cultural elements that make the region so distinctive. Wooded hills alternate with wide meadows, pastures, orchards, vineyards and dry grasslands, the result of centuries of cultivation. Four nature parks and Vienna''s Lainzer Tiergarten, an extensive game park, are among the 15 nature reserves in the region.

Biosphere reserves are ecosystems, recognised under uniform, internationally agreed criteria, where models of sustainable use of the biosphere are developed, tested and implemented. Together with local partners and authorities, the states of Lower Austria and Vienna are developing a model region for sustainability to meet the challenges of the 21st century.'),
  ('fr', 'aeolian-islands', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Les Îles Éoliennes (italien : Isole Eolie ; sicilien : Ìsuli Eoli), parfois appelées îles Lipari ou groupe de Lipari d''après leur plus grande île, sont un archipel volcanique de la mer Tyrrhénienne au nord de la Sicile, nommé d''après Éole, le souverain mythique des vents. Les habitants des îles sont connus sous le nom d''Éoliens (italien : Eoliani). Les îles comptaient une population permanente de 14 224 habitants lors du recensement [source datée] ; l''estimation officielle la plus récente est de 15 419 au 1er janvier [source datée]. Les Îles Éoliennes sont une destination touristique populaire en été et attirent jusqu''à 600 000 visiteurs par an.', 'Les îles Éoliennes, parfois appelées îles Lipari d''après la plus grande d''entre elles, forment un archipel volcanique de la mer Tyrrhénienne, au nord de la Sicile. Leur nom viendrait d''Éole, le maître mythique des vents. Leurs habitants sont appelés Éoliens (en italien : Eoliani). L''archipel est une destination estivale très prisée, qui accueille jusqu''à 600 000 visiteurs par an.'),
  ('fr', 'ariege-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'S''étendant sur environ 2 468 km2, il comprend 138 communes depuis le 1er janvier [dated source] et compte 46 000 habitants.', 'Un parc naturel régional d''environ 2 468 km2, qui couvre près de 40 % du département de l''Ariège.'),
  ('fr', 'bieszczady-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'En [source datée], le parc national a été classé au patrimoine mondial de l''UNESCO.', 'Les Bieszczady forment le troisième plus grand parc national de Pologne, à l''extrême sud-est du pays.'),
  ('fr', 'black-forest-central-north-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel de la Forêt-Noire Centre/Nord (en allemand : Naturpark Schwarzwald Mitte/Nord) est situé dans le Bade-Wurtemberg en Allemagne. Il s''étend sur une superficie de 3 750 km² et a été fondé en décembre [source datée]. À la date de [source datée], il s''agit du troisième plus grand parc naturel d''Allemagne.', 'Le parc naturel de la Forêt-Noire centrale et septentrionale (en allemand : Naturpark Schwarzwald Mitte/Nord) se trouve dans le Bade-Wurtemberg, en Allemagne, et couvre 3 750 km2.'),
  ('fr', 'breheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Breheimen National Park est un parc national fondé en [dated source]. Le parc est situé dans les municipalités de Skjåk et de Lom, dans le comté d''Innlandet, ainsi que dans la municipalité de Luster, dans le comté de Vestland, en Norvège. Il s''étend sur 1 671 kilomètres carrés dans la chaîne de montagnes de Breheimen. Le parc englobe certains des terrains les plus humides et les plus secs du pays, avec des paysages façonnés au cours de centaines de milliers d''années par les glaciers, les avalanches et d''autres processus géologiques. Les visiteurs y découvrent tout, des vallées verdoyantes de fermes de transhumance aux plateaux arides, en passant par des sommets vertigineux et des glaciers actifs.', 'Le parc national de Breheimen s''étend sur les communes de Skjåk et de Lom, dans le comté d''Innlandet, et sur celle de Luster, dans le comté de Vestland, en Norvège. Il couvre 1 671 kilomètres carrés du massif de Breheimen, avec certains des terrains les plus humides et les plus secs du pays, façonnés pendant des centaines de milliers d''années par les glaciers, les avalanches et d''autres processus géologiques. On y trouve aussi bien des vallées verdoyantes d''estive que des plateaux arides, des sommets élevés et des glaciers actifs.'),
  ('fr', 'breheimen-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le Breheimen National Park est un parc national fondé en [dated source].', 'Le parc national de Breheimen couvre 1 671 kilomètres carrés du massif de Breheimen, en Norvège.'),
  ('fr', 'catalan-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Créé en mars [source datée], il s''agit du tout premier parc naturel régional de la chaîne des Pyrénées.', 'Premier parc naturel régional des Pyrénées, il couvre le tiers ouest du département des Pyrénées-Orientales.'),
  ('fr', 'caves-of-barac', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Les Caves of Barać, également connues sous le nom de Barać Caves ou grottes de Barać, sont un groupe de grottes situées près du village de Nova Kršlja dans la municipalité de Rakovica, en Croatie. En 1892, les grottes furent ouvertes aux visiteurs avant d''être abandonnées et oubliées après la Seconde Guerre mondiale. En juillet [source datée], les Upper Caves of Barać ont été rouvertes au public.', 'Les grottes de Barać forment un ensemble de grottes près du village de Nova Kršlja, dans la commune de Rakovica, en Croatie. Ouvertes aux visiteurs en 1892, elles furent abandonnées puis oubliées après la Seconde Guerre mondiale. Les grottes supérieures de Barać ont depuis rouvert au public.'),
  ('fr', 'conca-dorupatrimoniogolfe-de-saint-florent', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Conca d''Oru, le vignoble de Patrimonio - golfe de Saint-Florent, a reçu le Label Grand Site de France en mars [source datée]. C’est le dix-septième site labellisé et le second en Corse.', 'La Conca d''Oru, le vignoble de Patrimonio et le golfe de Saint-Florent sont labellisés Grand Site de France. C''est le dix-septième site labellisé et le deuxième en Corse.'),
  ('fr', 'faerder-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Færder National Park est un parc national de la commune de Færder, dans le comté de Vestfold, en Norvège. Il s''agit principalement d''un parc marin, comprenant quelques îles et zones côtières à l''est des grandes îles de Nøtterøy et Tjøme. À l''est, le parc national borde le Ytre Hvaler National Park. Færder couvre une superficie de 340 km2, dont 325 km2 de mer et 15 km2 de terre. Le parc a été créé le 23 août [dated source]. Le parc comprend de grandes parties de l''archipel de Bolærne, ainsi que le phare protégé de Færder et les ruines du phare de Store Færder avec ses bâtiments protégés associés.', 'Le parc national de Færder se trouve dans la commune de Færder, dans le comté de Vestfold, en Norvège. C''est surtout un parc marin, qui comprend des îles et des zones côtières à l''est des grandes îles de Nøtterøy et de Tjøme, et qui jouxte à l''est le parc national d''Ytre Hvaler. Færder couvre 340 km2, dont 325 km2 de mer et 15 km2 de terre. Le parc englobe une grande partie de l''archipel de Bolærne, le phare protégé de Færder et les ruines du phare de Store Færder avec ses bâtiments protégés.'),
  ('fr', 'garrawilla-national-park-nsw', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Garrawilla National Park a été créé en décembre [dated source]. Il couvre une superficie de 937 hectares. Ce parc est situé sur le côté nord de l''Oxley Highway, à mi-chemin environ entre Coonabarabran et Mullaley, en Nouvelle-Galles du Sud, Australie.', 'Le parc national de Garrawilla couvre 937 hectares. Il se trouve au nord de l''Oxley Highway, à mi-chemin environ entre Coonabarabran et Mullaley, en Nouvelle-Galles du Sud (Australie).'),
  ('fr', 'garrawilla-national-park-nsw', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Garrawilla National Park : Garrawilla National Park a été créé en décembre [dated source].', 'Garrawilla National Park : Le parc national de Garrawilla borde l''Oxley Highway entre Coonabarabran et Mullaley (Nouvelle-Galles du Sud).'),
  ('fr', 'garrawilla-national-park-nsw', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Garrawilla National Park a été créé en décembre [dated source].', 'Le parc national de Garrawilla borde l''Oxley Highway entre Coonabarabran et Mullaley (Nouvelle-Galles du Sud).'),
  ('fr', 'grands-causses-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional des Grands Causses est un parc naturel régional français créé le 6 mai 1995 et renouvelé en [dated source]. Situé en Occitanie, à l’extrémité sud du Massif central, il s’étend sur le sud du département de l’Aveyron et le nord de l’Hérault.', 'Le parc naturel régional des Grands Causses a été créé le 6 mai 1995. Situé en Occitanie, à l''extrémité sud du Massif central, il couvre le sud du département de l''Aveyron et le nord de celui de l''Hérault.'),
  ('fr', 'harz-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'En [dated source], le Harz est devenu le premier parc national d''Allemagne à couvrir deux États fédéraux ; la partie orientale en Saxe-Anhalt se compose de 8 900 ha de terres et a été créée en 1990. En 1994, le gouvernement fédéral de Basse-Saxe a établi la partie occidentale du parc, couvrant 15 800 ha. En conséquence, le Harz National Park unifié se compose d''environ 24 700 ha. Le parc fait partie du réseau Natura [dated source] – la conservation de la nature européenne.

Harz National Park s''étend d''une chaîne de basses montagnes près de Herzberg dans la partie sud des montagnes, à travers le massif du Harz jusqu''à ses pentes septentrionales près de Bad Harzburg et Ilsenburg. Il offre toute la gamme des systèmes écologiques caractéristiques, des variations d''altitude, de pentes et de roches. L''altitude varie d''environ 240 m au nord et 270 m sur le bord sud jusqu''à 1 141 m sur le sommet du Brocken. Le parc offre un paysage écologiquement complexe et contient différentes zones de végétation.

Harz National Park est pratiquement inhabité, mais contient quelques colonies. Presque toutes les terres du parc sont boisées et appartiennent aux États fédéraux.

La recherche scientifique a identifié de nombreux habitats qui sont, selon les normes d''Europe centrale, assez proches d''un état naturel, tels que les régions ou zones de haute et moyenne altitude du Harz, les biotopes rocheux, de nombreux cours d''eau et une vaste zone de forêts de hêtres, d''épicéas et mixtes. Dans certaines sections, cependant, des changements écologiques dans le reboisement doivent être effectués afin de se rapprocher des conditions forestières naturelles d''origine.', 'Le parc national du Harz s''étend sur deux Länder : la partie orientale, en Saxe-Anhalt, créée en 1990, compte 8 900 ha, et la partie occidentale, créée par la Basse-Saxe en 1994, couvre 15 800 ha. L''ensemble couvre environ 24 700 ha et fait partie de Natura 2000, le réseau européen de protection de la nature.

Le parc s''étend des collines proches de Herzberg, au sud, à travers le massif du Harz jusqu''à ses versants nord près de Bad Harzburg et d''Ilsenburg. Il réunit toute la gamme des écosystèmes, des altitudes, des pentes et des roches caractéristiques, d''environ 240 m au nord et 270 m au sud jusqu''à 1 141 m au sommet du Brocken, avec plusieurs étages de végétation.

Le parc est presque inhabité, même s''il compte quelques hameaux. Presque toutes ses terres sont boisées et appartiennent aux Länder.

Les recherches ont mis en évidence de nombreux habitats proches de l''état naturel selon les critères d''Europe centrale : les étages supérieur et moyen du Harz, des biotopes rocheux, de nombreux cours d''eau et une vaste forêt de hêtres, d''épicéas et de forêts mixtes. Dans certains secteurs, une gestion forestière reste toutefois nécessaire pour retrouver des conditions plus proches de la forêt naturelle d''origine.'),
  ('fr', 'hump-ridge-track', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Hump Ridge Track, également appelé Tuatapere Hump Ridge Track, est un sentier de randonnée de 60–62 km situé en partie dans le Fiordland National Park en Nouvelle-Zélande. Le sentier a été ouvert en [dated source] et est géré de manière privée au nom du Tuatapere Hump Ridge Track Charitable Trust.', 'Le Hump Ridge Track, aussi appelé Tuatapere Hump Ridge Track, est un sentier de randonnée de 60 à 62 km qui traverse en partie le parc national de Fiordland, en Nouvelle-Zélande. Il est géré de façon privée pour le compte du Tuatapere Hump Ridge Track Charitable Trust.'),
  ('fr', 'jizerskohorske-buciny', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'La forêt de hêtres des montagnes de la Jizera est une réserve naturelle nationale, créée le 16 août 1999 par la fusion des sept réserves naturelles nationales d''origine Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantský cimmburi et Paličík par le décret n° 200 / 1999. En juillet [source datée], elles sont devenues le premier monument naturel tchèque inscrit sur la liste du patrimoine mondial de l''UNESCO.', 'Les hêtraies des monts de la Jizera (Jizerskohorské bučiny) forment une réserve naturelle nationale créée le 16 août 1999 par la fusion de sept réserves : Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantské cimbuří et Paličník. Elles ont été le premier site naturel tchèque inscrit au patrimoine mondial de l''UNESCO.'),
  ('fr', 'junkerdal-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Junkerdal National Park : Le parc de 682 kilomètres carrés a ouvert en [dated source].', 'Junkerdal National Park : Un parc national de 682 km2 à Saltdal et Fauske, dans le comté de Nordland, le long de la frontière suédoise.'),
  ('fr', 'junkerdal-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc de 682 kilomètres carrés a ouvert en [dated source].', 'Un parc national de 682 km2 à Saltdal et Fauske, dans le comté de Nordland, le long de la frontière suédoise.'),
  ('fr', 'kosterhavet-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Kosterhavet National Park est le premier parc marin national de Suède, inauguré en septembre [dated source]. Il fait partie de la mer Skagerrak et est situé dans les municipalités de Strömstad et Tanum dans le Bohuslän, comté de Västra Götaland, Suède. Il se compose de la mer et des rivages autour des îles Koster, à l''exclusion de tout le reste sur les îles. Au nord, il borde le parc marin norvégien d''Ytre Hvaler.', 'Le parc national de Kosterhavet est le premier parc national marin de Suède. Il fait partie du Skagerrak et s''étend sur les communes de Strömstad et de Tanum, dans le Bohuslän (comté de Västra Götaland). Il comprend la mer et les rivages autour des îles Koster, à l''exclusion du reste des îles, et jouxte au nord le parc marin norvégien d''Ytre Hvaler.'),
  ('fr', 'kotychi-and-strofylia-wetlands-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Kotychi and Strofylia Wetlands National Park : Il a été déclaré parc national en [dated source].', 'Kotychi and Strofylia Wetlands National Park : Zones humides et forêt protégées d''Achaïe et d''Élide : lac de Kotychi, forêt de Strofylia, cap Araxos.'),
  ('fr', 'kotychi-and-strofylia-wetlands-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il a été déclaré parc national en [dated source].', 'Zones humides et forêt protégées d''Achaïe et d''Élide : lac de Kotychi, forêt de Strofylia, cap Araxos.'),
  ('fr', 'langsua-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Langsua National Park a été établi en [dated source]. Le parc se compose d''une zone protégée totale de 537.1-square-kilometre . Il est situé dans le comté d''Innlandet en Norvège, et couvre des parties des municipalités de Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron et Nord-Fron.', 'Le parc national de Langsua protège 537,1 kilomètres carrés dans le comté d''Innlandet, en Norvège, sur une partie des communes d''Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron et Nord-Fron.'),
  ('fr', 'langsua-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Langsua National Park : Langsua National Park a été établi en [dated source].', 'Langsua National Park : Le parc national de Langsua protège 537,1 kilomètres carrés dans le comté d''Innlandet, en Norvège.'),
  ('fr', 'langsua-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Langsua National Park a été établi en [dated source].', 'Le parc national de Langsua protège 537,1 kilomètres carrés dans le comté d''Innlandet, en Norvège.'),
  ('fr', 'les-deux-caps-blanc-nez-gris-nez', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Les Deux-Caps Blanc-Nez, Gris-Nez : En [dated source], son périmètre passe de huit à dix-sept municipalités.', 'Les Deux-Caps Blanc-Nez, Gris-Nez : Un Grand Site de France sur la Côte d''Opale, entre Boulogne-sur-Mer et Calais, face à l''Angleterre.'),
  ('fr', 'les-deux-caps-blanc-nez-gris-nez', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'En [dated source], son périmètre passe de huit à dix-sept municipalités.', 'Un Grand Site de France sur la Côte d''Opale, entre Boulogne-sur-Mer et Calais, face à l''Angleterre.'),
  ('fr', 'liechtensteinklamm', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Liechtensteinklamm est ouvert tous les jours de début mai au 30 septembre [dated source] de 09:00 à 18:00 (dernière admission à 18:00).', ''),
  ('fr', 'liechtensteinklamm', 'metaDescription', 'fields', '{metaDescription}'::text[], 'CLEAR', 'Liechtensteinklamm : Liechtensteinklamm est ouvert tous les jours du début mai au 30 septembre [source datée] de 09h00 à 18h00 (dernière', ''),
  ('fr', 'liechtensteinklamm', 'tagline', 'fields', '{tagline}'::text[], 'CLEAR', 'Liechtensteinklamm est ouvert tous les jours du début mai au 30 septembre [source datée] de 09h00 à 18h00 (dernière', ''),
  ('fr', 'lierne-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Lierne National Park se situe dans la municipalité de Lierne, dans le comté de Trøndelag, en Norvège. Le parc de 333 kilomètres carrés a été établi le 17 décembre [dated source] par une résolution royale. Le parc couvre 333 kilomètres carrés de terres le long de la frontière avec la Suède. Le parc se situe à l''est des zones habitées de la municipalité de Lierne, à environ 12 kilomètres au sud-est du village de Sandvika et à environ 6 kilomètres au nord-est du village de Mebygda.', 'Le parc national de Lierne se trouve dans la commune de Lierne, dans le comté de Trøndelag, en Norvège. Il couvre 333 kilomètres carrés le long de la frontière suédoise, à l''est des zones habitées de Lierne, à environ 12 kilomètres au sud-est du village de Sandvika et à 6 kilomètres au nord-est de Mebygda.'),
  ('fr', 'lomsdal-visten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Lomsdal–Visten National Park est un parc national norvégien qui a été créé le 26 juin [source datée]. Le parc consiste en une zone protégée totale de 1 102 kilomètres carrés. Il est situé dans le comté de Nordland, en Norvège, et couvre des parties de la municipalité de Brønnøy, de la municipalité de Vevelstad, de la municipalité de Grane et de la municipalité de Vefsn.', 'Le parc national de Lomsdal-Visten est un parc national norvégien d''une superficie protégée de 1 102 kilomètres carrés. Il se trouve dans le comté de Nordland et s''étend sur une partie des communes de Brønnøy, Vevelstad, Grane et Vefsn.'),
  ('fr', 'loonse-en-drunense-duinen', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Loonse en Drunense Duinen : Il est désigné comme parc national depuis [dated source].', 'Loonse en Drunense Duinen : Un parc national de 35 km2 entre Tilburg, Waalwijk et Bois-le-Duc, dans le sud des Pays-Bas.'),
  ('fr', 'loonse-en-drunense-duinen', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il est désigné comme parc national depuis [dated source].', 'Un parc national de 35 km2 entre Tilburg, Waalwijk et Bois-le-Duc, dans le sud des Pays-Bas.'),
  ('fr', 'lorship-bertiz-natural-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Lorship Bertiz Natural Park : Le Natural Park Señorío de Bertiz (officiellement Bertizko Jaurerria Parke Naturala) [dated source] ha, se situ', 'Lorship Bertiz Natural Park : Le Señorío de Bertiz est un parc naturel du nord-ouest de la Navarre, en Espagne, déclaré en 1984.'),
  ('fr', 'lorship-bertiz-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le Natural Park Señorío de Bertiz (officiellement Bertizko Jaurerria Parke Naturala) [dated source] ha, se situ', 'Le Señorío de Bertiz est un parc naturel du nord-ouest de la Navarre, en Espagne, déclaré en 1984.'),
  ('fr', 'marine-natural-park-of-picardy-and-opale-coast', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel marin des estuaires picards et de la mer d''Opale est un parc naturel marin français créé en décembre [dated source]. Il est situé face aux sept fleuves côtiers, du sud au nord, la Bresle, la Somme, l''Authie, la Canche, la Liane, le Wimereux et la Slack. Son siège social est situé à Écault sur le territoire de Saint-Étienne-au-Mont, dans le Pas-de-Calais.', 'Le parc naturel marin des estuaires picards et de la mer d''Opale s''étend au large de sept fleuves côtiers : du sud au nord, la Bresle, la Somme, l''Authie, la Canche, la Liane, le Wimereux et la Slack. Son siège se trouve à Écault, sur la commune de Saint-Étienne-au-Mont (Pas-de-Calais).'),
  ('fr', 'marker-wadden-in-het-markermeer', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Marker Wadden in het Markermeer : La première île a été inaugurée le 24 septembre [dated source].', 'Marker Wadden in het Markermeer : Les Marker Wadden sont un archipel artificiel et une réserve naturelle du lac Markermeer, aux Pays-Bas.'),
  ('fr', 'marker-wadden-in-het-markermeer', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'La première île a été inaugurée le 24 septembre [dated source].', 'Les Marker Wadden sont un archipel artificiel et une réserve naturelle du lac Markermeer, aux Pays-Bas.'),
  ('fr', 'midden-delfland', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Midden-Delfland (en néerlandais : [ˌmɪdəˈdɛlflɑnt] ) est une municipalité de la région du Westland dans la province de Hollande-Méridionale aux Pays-Bas. Elle comptait une population de 19 355 habitants en [source datée] et couvre une superficie de 49,38 km2 dont 2,19 km2 d''eau.', 'Midden-Delfland est une commune de la région du Westland, dans la province de Hollande-Méridionale, aux Pays-Bas. Elle couvre 49,38 km2, dont 2,19 km2 d''eau.'),
  ('fr', 'midden-delfland', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Midden-Delfland : Il comptait une population de 19 355 habitants en [dated source] et couvre une superficie de 49,38 km2, dont 2,19 km2 d''eau.', 'Midden-Delfland : Midden-Delfland est une commune de 49,38 km2 située dans la région du Westland, en Hollande-Méridionale.'),
  ('fr', 'midden-delfland', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il comptait une population de 19 355 habitants en [dated source] et couvre une superficie de 49,38 km2, dont 2,19 km2 d''eau.', 'Midden-Delfland est une commune de 49,38 km2 située dans la région du Westland, en Hollande-Méridionale.'),
  ('fr', 'mont-ventoux', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional du Mont-Ventoux, en provençal pargue dóu Ventours, est un parc naturel régional créé par décret le 28 juillet [dated source]. C''est le 55e parc naturel régional créé en France, et le 9e en Provence-Alpes-Côte d''Azur.', 'Le parc naturel régional du Mont-Ventoux (en provençal : pargue dóu Ventours) est le 55e parc naturel régional créé en France et le 9e en Provence-Alpes-Côte d''Azur.'),
  ('fr', 'mors-and-hanklit', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mors ou Morsø est une île située dans le détroit peu profond appelé Limfjorden, entre la péninsule du Jutland au Danemark et l''île de Vendsyssel-Thy (North Jutlandic Island). Elle a une superficie de 367,3 km2 et, au 1er janvier [dated source], elle comptait une population de 19 486 habitants. La ville principale de l''île s''appelle Nykøbing Mors. Sur le plan géologique, Mors est unique. Comme l''île voisine de Fur, elle est connue pour ses gisements de diatomite, localement appelés « moler ».', 'Mors (Morsø) est une île du Limfjord, le détroit peu profond qui sépare la péninsule du Jutland de l''île de Vendsyssel-Thy, au Danemark. Elle couvre 367,3 km2 et sa ville principale est Nykøbing Mors. Sur le plan géologique, Mors est unique : comme l''île voisine de Fur, elle est connue pour ses gisements de diatomite, appelée localement « moler ».'),
  ('fr', 'mors-and-hanklit', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Mors and Hanklit : Il a une superficie de 367,3 km2 et, au 1er janvier [source datée], il comptait 19 486 habitants.', 'Mors and Hanklit : Mors est une île de 367,3 km2 dans le Limfjord, au Danemark, connue pour ses gisements de diatomite (moler).'),
  ('fr', 'mors-and-hanklit', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Il a une superficie de 367,3 km2 et, au 1er janvier [source datée], il comptait 19 486 habitants.', 'Mors est une île de 367,3 km2 dans le Limfjord, au Danemark, connue pour ses gisements de diatomite (moler).'),
  ('fr', 'morskie-oko', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Morskie Oko, ou l''Œil de la Mer en français, est le plus grand et le quatrième lac le plus profond des montagnes des Tatras, dans le sud de la Pologne. Il est situé au cœur du Tatra National Park, dans la vallée de Rybi Potok, au sein de la chaîne des Hautes Tatras, au pied des sommets Mięguszowiecki, dans la voïvodie de Petite-Pologne. En [dated source], le Wall Street Journal a reconnu le lac comme l''un des cinq plus beaux lacs du monde.', 'Le Morskie Oko (« l''Œil de la mer ») est le plus grand et le quatrième plus profond lac des Tatras, dans le sud de la Pologne. Il se trouve au cœur du parc national des Tatras, dans la vallée de Rybi Potok, dans les Hautes Tatras, au pied des sommets Mięguszowiecki, en Petite-Pologne.'),
  ('fr', 'nationaal-park-de-sallandse-heuvelrug', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Nationaal Park De Sallandse Heuvelrug : En [dated source], le gouvernement néerlandais a changé le statut de la zone en Parc National.', 'Nationaal Park De Sallandse Heuvelrug : La Sallandse Heuvelrug est un parc national de l''Overijssel, entre les communes de Hellendoorn et de Holten.'),
  ('fr', 'nationaal-park-de-sallandse-heuvelrug', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'En [dated source], le gouvernement néerlandais a changé le statut de la zone en Parc National.', 'La Sallandse Heuvelrug est un parc national de l''Overijssel, entre les communes de Hellendoorn et de Holten.'),
  ('fr', 'nationaal-park-duinen-van-texel', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Nationaal Park Duinen van Texel : Le parc couvre environ 43 km2 et a obtenu le statut de parc national en [source datée].', 'Nationaal Park Duinen van Texel : Le parc national Duinen van Texel couvre environ 43 km2 de dunes et de plaines côtières sur l''île de Texel.'),
  ('fr', 'nationaal-park-duinen-van-texel', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc couvre environ 43 km2 et a obtenu le statut de parc national en [source datée].', 'Le parc national Duinen van Texel couvre environ 43 km2 de dunes et de plaines côtières sur l''île de Texel.'),
  ('fr', 'national-park-drina', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Drina National Park est le quatrième parc national de Bosnie-Herzégovine, et le troisième de la Republika Srpska. Il a été fondé en [dated source]. La ville la plus proche est Srebrenica. Il est situé de l''autre côté de la Drina par rapport au Tara National Park en Serbie.', 'Le parc national de la Drina est le quatrième parc national de Bosnie-Herzégovine et le troisième de la République serbe de Bosnie. La ville la plus proche est Srebrenica. Il se trouve sur la rive opposée de la Drina, face au parc national de Tara, en Serbie.'),
  ('fr', 'national-park-of-eastern-macedonia-and-thrace', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le National Park of Eastern Macedonia - Thrace a été fondé en [dated source] et incluait les zones déjà protégées de D. Nestos, L. Vistonidas, L. Ismaridas et leur zone élargie. Le complexe de zones humides du parc national est l''un des plus importants de Grèce, en raison de sa vaste superficie et de sa grande valeur biologique, esthétique, scientifique, géomorphologique et pédagogique. L''objectif du parc national est de protéger efficacement les habitats et les espèces rares de flore et de faune endémiques et reproductrices dans la région.', 'Le parc national de Macédoine-Orientale-et-Thrace englobe le delta du Nestos, le lac Vistonida, le lac Ismarida, déjà protégés, ainsi que leurs environs. Son complexe de zones humides est l''un des plus importants de Grèce par sa superficie et sa grande valeur biologique, paysagère, scientifique, géomorphologique et pédagogique. Le parc vise à protéger les habitats et les espèces rares de flore et de faune endémiques ou nicheuses de la région.'),
  ('fr', 'national-park-of-messolonghi-aitoliko-lagoons', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'National Park of Messolonghi - Aitoliko lagoons : Créé en [dated source], il englobe le plus grand complexe lagunaire du pays.', 'National Park of Messolonghi - Aitoliko lagoons : Le parc national englobe le plus grand complexe lagunaire de Grèce, au nord-ouest du golfe de Patras.'),
  ('fr', 'national-park-of-messolonghi-aitoliko-lagoons', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Créé en [dated source], il englobe le plus grand complexe lagunaire du pays.', 'Le parc national englobe le plus grand complexe lagunaire de Grèce, au nord-ouest du golfe de Patras.'),
  ('fr', 'nationalpark-thy', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Thy National Park est une zone de parc national située à Thy, au Danemark, ouverte au public le 22 août [dated source]. Il est situé dans le nord-ouest du Jutland, le long de la côte de Hanstholm à Agger Tange, et s''étend sur 55 km du nord au sud et sur 5 à 12 km d''est en ouest. La superficie totale du parc national est de 244 km2.', 'Le parc national de Thy se trouve dans la région de Thy, au Danemark. Il s''étend dans le nord-ouest du Jutland, le long de la côte de Hanstholm à Agger Tange, sur 55 km du nord au sud et 5 à 12 km d''est en ouest. Sa superficie totale est de 244 km2.'),
  ('fr', 'natural-park-of-serra-d-irta', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Serra d''Irta Natural Park (Valencien : Parc Natural de la Serra d''Irta, Espagnol : Parque Natural de la Sierra de Irta) est un parc naturel de la Communauté valencienne, au sud de l''Espagne. Il contient 7 744 hectares de terres, ainsi qu''un littoral de réserve naturelle marine de la mer Méditerranée adjacente. Il a été déclaré zone protégée en [dated source].', 'Le parc naturel de la Serra d''Irta (en valencien : Parc Natural de la Serra d''Irta ; en espagnol : Parque Natural de la Sierra de Irta) se trouve dans la Communauté valencienne, en Espagne. Il couvre 7 744 hectares de terres ainsi qu''une réserve naturelle marine le long du littoral méditerranéen voisin.'),
  ('fr', 'naturpark-nissum-fjord', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel Nissum Fjord a été mis en place comme projet pilote à la demande du Nissum Fjord Network en mai [dated source]. Le parc naturel s''étend sur 22 670 hectares autour de Nissum Fjord et est le troisième plus grand parc naturel du Danemark. Le parc naturel a été approuvé par le Open Air Council le 12 décembre [dated source].', 'Le parc naturel du Nissum Fjord s''étend sur 22 670 hectares autour du Nissum Fjord ; c''est le troisième plus grand parc naturel du Danemark.'),
  ('fr', 'naturpark-nissum-fjord', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Naturpark Nissum Fjord : Le parc naturel a été approuvé par le Open Air Council le 12 décembre [dated source].', 'Naturpark Nissum Fjord : Le parc naturel du Nissum Fjord couvre 22 670 hectares autour du fjord ; c''est le troisième du Danemark.'),
  ('fr', 'naturpark-nissum-fjord', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc naturel a été approuvé par le Open Air Council le 12 décembre [dated source].', 'Le parc naturel du Nissum Fjord couvre 22 670 hectares autour du fjord ; c''est le troisième du Danemark.'),
  ('fr', 'north-pindos-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'North Pindos National Park mesure 230 km de long et 70 km de large, fondé en [source datée] et est considéré comme l''une des zones les plus importantes au niveau national et européen. De plus, la variété des espèces rares doit être mentionnée car presque tous les grands mammifères de la Grèce continentale sont présents dans la zone. Un total de 60 espèces de mammifères, 166 espèces d''oiseaux, 30 espèces de reptiles, 14 espèces d''amphibiens et 17 espèces de poissons se trouvent dans le parc.', 'Le parc national du Pinde du Nord mesure 230 km de long sur 70 km de large et compte parmi les zones les plus importantes de Grèce et d''Europe. Presque tous les grands mammifères de la Grèce continentale y vivent : on y recense 60 espèces de mammifères, 166 d''oiseaux, 30 de reptiles, 14 d''amphibiens et 17 de poissons.'),
  ('fr', 'ostmarka-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Østmarka National Park est un parc national norvégien créé en [dated source]. Il couvre une superficie de 54 km2 à Østmarka, Oslo et dans les municipalités d''Akershus : Nordre Follo, Lørenskog, Røllen et Enebakk.', 'Le parc national d''Østmarka est un parc national norvégien qui couvre 54 km2 de la forêt d''Østmarka, à Oslo et dans les communes d''Akershus de Nordre Follo, Lørenskog, Rælingen et Enebakk.'),
  ('fr', 'paluma-range-national-park-qld', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'À l''occasion de la Journée des parcs nationaux [source datée], le gouvernement de l''État du Queensland a annoncé l''ajout de 6 510 hectares à Paluma Range National Park.', ''),
  ('fr', 'parc-naturel-regional-alpilles', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Alpilles Regional Nature Park est un parc naturel régional français créé en [dated source], en Provence-Alpes-Côte d''Azur dans le département des Bouches-du-Rhône. Il s''étend sur le massif calcaire préalpin des Alpilles et ses environs immédiats .', 'Le parc naturel régional des Alpilles se trouve dans les Bouches-du-Rhône, en Provence-Alpes-Côte d''Azur. Il s''étend sur le massif calcaire préalpin des Alpilles et ses abords immédiats.'),
  ('fr', 'parc-naturel-regional-aubrac', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Aubrac Regional Natural Park est un parc naturel régional français créé par décret le 23 mai [dated source], dont le périmètre occupe environ 2 282 km2 répartis sur 64 communes des trois départements de l''Aveyron, de la Lozère et du Cantal, autour du plateau du même nom. C''est le 53ème Parc Naturel Régional français.', 'Le parc naturel régional de l''Aubrac couvre environ 2 282 km2 répartis sur 64 communes de l''Aveyron, de la Lozère et du Cantal, autour du plateau de l''Aubrac. C''est le 53e parc naturel régional français.'),
  ('fr', 'parc-naturel-regional-de-guyane', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional de Guyane est un parc naturel régional français créé en [dated source] en Guyane. Il est divisé en trois parties terrestres et deux portions maritimes, et couvre le territoire de six communes : Iracoubo, Mana, Ouanary, Roura, Saint-Georges et Sinnamary.', 'Le parc naturel régional de la Guyane se compose de trois parties terrestres et de deux parties maritimes. Il couvre le territoire de six communes : Iracoubo, Mana, Ouanary, Roura, Saint-Georges et Sinnamary.'),
  ('fr', 'parc-naturel-regional-des-baronnies-provencales', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel régional des Baronnies provençales s''étend sur un massif alpin entre les départements de la Drôme et des Hautes-Alpes dans le sud-est de la France. Ce parc naturel régional a été créé le 26 janvier [dated source]. Il couvre 104 communes en tout ou en partie.', 'Le parc naturel régional des Baronnies provençales s''étend sur un massif alpin entre la Drôme et les Hautes-Alpes, dans le sud-est de la France. Il couvre tout ou partie de 104 communes.'),
  ('fr', 'parc-naturel-regional-des-baronnies-provencales', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Parc naturel régional des Baronnies provençales : Ce parc naturel régional a été créé le 26 janvier [dated source].', 'Parc naturel régional des Baronnies provençales : Un parc naturel régional sur un massif alpin entre la Drôme et les Hautes-Alpes, qui s''étend sur 104 communes.'),
  ('fr', 'parc-naturel-regional-des-baronnies-provencales', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Ce parc naturel régional a été créé le 26 janvier [dated source].', 'Un parc naturel régional sur un massif alpin entre la Drôme et les Hautes-Alpes, qui s''étend sur 104 communes.'),
  ('fr', 'parc-naturel-regional-des-prealpes-d-azur', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional des Préalpes d''Azur est un parc naturel régional français créé le 30 mars [dated source] et situé dans le département des Alpes-Maritimes, en région Provence-Alpes-Côte d''Azur. Il est précisément situé dans les Préalpes de Grasse, entre les vallées de la Siagne, du Loup, de la Cagne, de l''Estéron et du Var.', 'Le parc naturel régional des Préalpes d''Azur se trouve dans les Alpes-Maritimes, en Provence-Alpes-Côte d''Azur. Il s''étend sur les Préalpes de Grasse, entre les vallées de la Siagne, du Loup, de la Cagne, de l''Estéron et du Var.'),
  ('fr', 'parc-naturel-regional-medoc', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional du Médoc est un parc naturel régional situé dans le département de la Gironde, en région Nouvelle-Aquitaine, classé par décret du 24 mai [dated source]. Il devient le 54e parc naturel régional de France et couvre une partie de la région naturelle du Médoc.', 'Le parc naturel régional du Médoc se trouve en Gironde, dans la région Nouvelle-Aquitaine. C''est le 54e parc naturel régional de France ; il couvre une partie de la région naturelle du Médoc.'),
  ('fr', 'parc-naturel-regional-oisepays-de-france', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional Oise-Pays de France, créé le 13 janvier [dated source] par décret du Premier ministre, s''étend sur 70 communes des départements de l''Oise et du Val-d''Oise. C''est l''un des rares parcs répartis sur deux régions administratives, le quatrième PNR des Hauts de France et le quatrième en Île-de-France.', 'Le parc naturel régional Oise-Pays de France couvre 70 communes de l''Oise et du Val-d''Oise. C''est l''un des rares parcs répartis sur deux régions : le quatrième PNR des Hauts-de-France et le quatrième d''Île-de-France.'),
  ('fr', 'parco-dei-monti-sicani', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc des Sicani Mountains était un parc naturel régional de Sicile établi le 19 décembre [dated source] et supprimé en juillet [dated source]. Il comprenait 12 municipalités dans les territoires du libre consortium municipal d''Agrigento et de la ville métropolitaine de Palermo, en Sicile.', 'Le parc des monts Sicani était un parc naturel régional de Sicile, supprimé depuis. Il comprenait 12 communes du libre consortium communal d''Agrigente et de la ville métropolitaine de Palerme.'),
  ('fr', 'parco-naturale-regionale-bosco-incoronata', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel régional Bosco Incoronata est une zone naturelle protégée établie en [dated source] le long de la rivière Cervaro, à environ 12 kilomètres de la ville de Foggia, au cœur du Tavoliere des Pouilles.', 'Le parc naturel régional du Bosco Incoronata est une zone naturelle protégée le long du Cervaro, à une douzaine de kilomètres de Foggia, au cœur de la plaine du Tavoliere, dans les Pouilles.'),
  ('fr', 'parco-naturale-regionale-bosco-incoronata', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Parco naturale regionale Bosco Incoronata : Le parc naturel régional Bosco Incoronata est une zone naturelle protégée établie en [dated source] le long de la', 'Parco naturale regionale Bosco Incoronata : Une zone naturelle protégée le long du Cervaro, à une douzaine de kilomètres de Foggia, dans les Pouilles.'),
  ('fr', 'parco-naturale-regionale-bosco-incoronata', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc naturel régional Bosco Incoronata est une zone naturelle protégée établie en [dated source] le long de la', 'Une zone naturelle protégée le long du Cervaro, à une douzaine de kilomètres de Foggia, dans les Pouilles.'),
  ('fr', 'parco-naturale-regionale-del-vulture', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel régional du Vulture est une zone naturelle protégée créée en novembre [source datée]. Ce parc régional comprend la zone du Vulture ainsi qu''une partie des territoires communaux d''Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte et San Fele, appartenant tous à la province de Potenza.', 'Le parc naturel régional du Vulture est une zone naturelle protégée qui comprend le secteur du Vulture et une partie des communes d''Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte et San Fele, toutes situées dans la province de Potenza.'),
  ('fr', 'parco-naturale-regionale-del-vulture', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Parco naturale regionale del Vulture : Le parc naturel régional du Vulture est une zone naturelle protégée créée en novembre [source datée]. Ce parc rég', 'Parco naturale regionale del Vulture : Une zone naturelle protégée autour du Vulture, dont une partie de Melfi, dans la province de Potenza.'),
  ('fr', 'parco-naturale-regionale-del-vulture', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc naturel régional du Vulture est une zone naturelle protégée créée en novembre [source datée]. Ce parc rég', 'Une zone naturelle protégée autour du Vulture, dont une partie de Melfi, dans la province de Potenza.'),
  ('fr', 'parco-naturale-regionale-litorale-di-ugento', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc régional Litorale di Ugento est une zone naturelle protégée des Pouilles établie par la loi régionale n° 13 du 28 mai [dated source]. Le parc est situé le long de la côte ionienne, dans la partie la plus méridionale de la péninsule du Salento, et est bordé par les villes de Torre San Giovanni et Lido Marini. Il protège, sur une profondeur d''environ trois kilomètres depuis la côte et sur une longueur de huit, une séquence côtière de grande valeur, composée d''un système dunaire et rétrodunaire, d''une série de bassins de marée et de canaux de liaison, d''un imposant récif fossile avec des gravine et de la zone la plus étendue de maquis méditerranéen du Salento.', 'Le parc régional du littoral d''Ugento est une zone naturelle protégée des Pouilles. Il longe la côte ionienne, à l''extrémité sud de la péninsule du Salento, entre Torre San Giovanni et Lido Marini. Sur environ trois kilomètres de profondeur et huit de longueur, il protège une séquence côtière très précieuse : un système de dunes et d''arrière-dunes, des bassins et des canaux de liaison, un imposant récif fossile et la plus vaste étendue de maquis méditerranéen du Salento.'),
  ('fr', 'parco-naturale-regionale-terra-delle-gravine', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel Terra delle Gravine est une zone naturelle protégée établie dans les Pouilles en [dated source]. La zone couvre les provinces de Brindisi et de Tarente, dans la région des Murge.', 'Le parc naturel de la Terra delle Gravine est une zone naturelle protégée des Pouilles, qui s''étend sur une partie des provinces de Brindisi et de Tarente, dans les Murges.'),
  ('fr', 'ponga-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel de Ponta est un espace naturel protégé espagnol, situé dans la zone centrale de la chaîne Cantábrica avec une zone protégée de 20 533 ha, dont la majeure partie constitue le conseil municipal de Ponta. Il était initialement prévu d''être inclus dans le Reds Park à la fin de la période et son nom en tant que parc naturel est venu plus tard avec sa propre identité. Il a été déclaré par la loi 4 / [dated source].', 'Le parc naturel de Ponga est un espace naturel protégé espagnol au centre de la cordillère Cantabrique, d''une superficie protégée de 20 533 ha, situé en majeure partie sur la commune de Ponga.'),
  ('fr', 'reinheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reinheimen National Park est un parc national en Norvège qui a été établi en [dated source]. Le parc se compose d''une zone montagneuse protégée continue de 1 969 kilomètres carrés. Il est situé dans les comtés de Møre og Romsdal et d''Innlandet en Norvège. Le parc comprend des parties des municipalités de Lesja, Skjåk, Vågå, Lom, Fjord et Rauma. Le parc se compose d''une grande partie de la chaîne de montagnes Tafjordfjella ainsi que de l''habitat des rennes dans la partie nord de la vallée d''Ottadalen.', 'Le parc national de Reinheimen est un parc national norvégien qui protège un massif montagneux d''un seul tenant de 1 969 kilomètres carrés dans les comtés de Møre og Romsdal et d''Innlandet. Il comprend une partie des communes de Lesja, Skjåk, Vågå, Lom, Fjord et Rauma, une grande partie du massif du Tafjordfjella et l''habitat des rennes au nord de la vallée d''Ottadalen.'),
  ('fr', 'reynisdrangar', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Reynisdrangar : Dans [dated source], Reynisfjara [ˈreiːnɪsˌfjaːra] a été classée sixième meilleure plage au monde.', 'Reynisdrangar : Des aiguilles de basalte au pied du Reynisfjall, près de Vík í Mýrdal, bordées par une plage de sable noir.'),
  ('fr', 'reynisdrangar', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Dans [dated source], Reynisfjara [ˈreiːnɪsˌfjaːra] a été classée sixième meilleure plage au monde.', 'Des aiguilles de basalte au pied du Reynisfjall, près de Vík í Mýrdal, bordées par une plage de sable noir.'),
  ('fr', 'reynisfjara', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reynisfjara est une plage de sable noir populaire dans le sud de l''Islande, près de la ville de Vík í Mýrdal. Elle fait partie du Katla UNESCO Global Geopark sur un terrain privé. En février [dated source], après des semaines de fortes vagues et de vents d''est, une partie des colonnes de basalte emblématiques s''est effondrée en même temps qu''une érosion importante de la plage. Avec le retour des vents d''ouest en mars, Reynisfjara devrait retrouver son apparence familière.', 'Reynisfjara est une plage de sable noir très fréquentée du sud de l''Islande, près de la ville de Vík í Mýrdal. Elle fait partie du géoparc mondial UNESCO de Katla et se trouve sur un terrain privé.'),
  ('fr', 'rhine-falls', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Rhine Falls : Du 13 novembre [dated source] au 3 janvier [dated source] : L''illumination du Schloss Laufen sur le Rhine Fa', 'Rhine Falls : La plus grande chute d''eau d''Europe, entre les châteaux de Laufen et de Wörth, visible depuis le pont des CFF.'),
  ('fr', 'rhine-falls', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Du 13 novembre [dated source] au 3 janvier [dated source] : L''illumination du Schloss Laufen sur le Rhine Fa', 'La plus grande chute d''eau d''Europe, entre les châteaux de Laufen et de Wörth, visible depuis le pont des CFF.'),
  ('fr', 'rohkunborri-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Rohkunborri National Park est un parc national du comté de Troms, en Norvège, qui a été établi en [dated source]. Le parc consiste en une zone protégée de 571 kilomètres carrés et est situé dans la municipalité de Bardu, le long de la frontière avec la Suède, à environ 30 kilomètres au sud-est du village de Setermoen et à environ 50 kilomètres au nord-est de la ville de Narvik.', 'Le parc national de Rohkunborri se trouve dans le comté de Troms, en Norvège, et protège 571 kilomètres carrés. Il s''étend dans la commune de Bardu, le long de la frontière suédoise, à environ 30 kilomètres au sud-est du village de Setermoen et à une cinquantaine de kilomètres au nord-est de la ville de Narvik.'),
  ('fr', 'rosalia-kogelberg-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Dans le cadre du projet « Expérience de la nature sans barrières Rosalia-Kogelberg », une expérience de randonnée et de nature pour tous les sens a été créée entre [dated source] et [dated source]. Le projet comprenait, entre autres, la conception et la construction d''un total de onze stations d''expérience et de repos sans barrières le long de ce qu''on appelle l''Eulenweg ou le long du « Tour Teichwiesen ».', 'Dans le cadre du projet « Nature sans obstacles Rosalia-Kogelberg », un parcours de randonnée et de découverte de la nature pour tous les sens a été aménagé. Le projet a notamment permis de concevoir et de construire onze stations de découverte et de repos accessibles le long de l''Eulenweg et du « Tour Teichwiesen ».'),
  ('fr', 'saimaa-unesco-global-geopark', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Saimaa UNESCO Global Geopark : La zone a reçu le statut de UNESCO Global Geopark en [dated source].', 'Saimaa UNESCO Global Geopark : Un géoparc mondial UNESCO de 65 géosites autour du lac Saimaa, le plus grand lac de Finlande.'),
  ('fr', 'saimaa-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'La zone a reçu le statut de UNESCO Global Geopark en [dated source].', 'Un géoparc mondial UNESCO de 65 géosites autour du lac Saimaa, le plus grand lac de Finlande.'),
  ('fr', 'sainte-baume-regional-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Sainte-Baume Regional Nature Park est un parc naturel régional créé par décret le 20 décembre [dated source], avec un périmètre d''environ 84 367 ha répartis entre les deux départements des Bouches-du-Rhône et du Var, autour du massif du même nom. C''est le 52ème parc naturel régional français.', 'Le parc naturel régional de la Sainte-Baume couvre environ 84 367 ha répartis entre les Bouches-du-Rhône et le Var, autour du massif du même nom. C''est le 52e parc naturel régional français.'),
  ('fr', 'salpausselka-unesco-global-geopark', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Salpausselkä UNESCO Global Geopark : Salpausselkä Geopark a été accepté le 13 avril [source datée].', 'Salpausselkä UNESCO Global Geopark : Le géoparc de Salpausselkä s''étend sur Lahti, Hollola, Asikkala, Heinola, Sysma et Padasjoki, en Finlande.'),
  ('fr', 'salpausselka-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Salpausselkä Geopark a été accepté le 13 avril [source datée].', 'Le géoparc de Salpausselkä s''étend sur Lahti, Hollola, Asikkala, Heinola, Sysma et Padasjoki, en Finlande.'),
  ('fr', 'salzburger-lungau-and-karntner-nockberge-biosphere', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Salzburger Lungau et les Carinthian Nockberge adjacents ont été classés Réserve de biosphère par l''UNESCO en juillet [source datée]. Elle couvre l''ensemble du district salzbourgeois de Tamsweg (Lungau) et les zones adjacentes des Nockberge en Carinthie. Cela fait de cette zone bordant les États fédéraux de Salzbourg et de Carinthie une « région modèle pour le développement durable ».', 'Le Lungau salzbourgeois et les Nockberge carinthiens voisins sont reconnus par l''UNESCO comme parc de biosphère. Celui-ci couvre tout le district salzbourgeois de Tamsweg (Lungau) et les zones voisines des Nockberge, en Carinthie, ce qui fait de cette région frontalière une « région modèle pour le développement durable ».'),
  ('fr', 'sequoia-park-of-monte-cabezon', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Les éléments suivants sont un « espace naturel protégé » de Cantabrie, déclaré Monument Naturel par le Décret 41 / [dated source] du Gouvernement de Cantabrie et inclus dans le Réseau des Espaces Naturels Protégés par la Loi de Cantabrie 4 / [dated source] du 19 mai.', 'Le parc des séquoias du mont Cabezón est un espace naturel protégé de Cantabrie, déclaré monument naturel par le gouvernement de Cantabrie et intégré au réseau des espaces naturels protégés de la région.'),
  ('fr', 'sequoia-park-of-monte-cabezon', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Sequoia Park of Monte Cabezón : Les éléments suivants sont un « espace naturel protégé » de Cantabrie, déclaré Monument naturel par le décret 41 / [dated ', 'Sequoia Park of Monte Cabezón : Le parc des séquoias du mont Cabezón est un monument naturel et un espace naturel protégé de Cantabrie.'),
  ('fr', 'sequoia-park-of-monte-cabezon', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Les éléments suivants sont un « espace naturel protégé » de Cantabrie, déclaré Monument naturel par le décret 41 / [dated ', 'Le parc des séquoias du mont Cabezón est un monument naturel et un espace naturel protégé de Cantabrie.'),
  ('fr', 'serra-da-encina-da-lastra-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Sierra de la Lasse Natural Park () () () () est un espace naturel protégé espagnol situé dans le nord-est de la province d''Orense, dans la municipalité de Rubiana, Valdeoras, et a été déclaré Parc Naturel en [dated source] par le Conseil de Galice. Il a une superficie de 3151.67 ha et une altitude moyenne de 684 m. C''est une vallée calcaire aux pentes prononcées et aux falaises avec une forêt méditerranéenne. Une zone d''intérêt public particulièrement importante, notamment pour ses populations de rapaces, parmi lesquelles la présence de l''Aigle royal et du Faucon pèlerin. L''abondance de grottes - appelées ici des pelles - conduit à l''existence de nombreuses colonies de chauves-souris, les plus importantes de Galice. Un autre point d''intérêt réside dans la présence de zones de pâturage de type méditerranéen caractéristiques des zones de montagnes rocheuses.)', 'Le parc naturel de la Serra da Enciña da Lastra est un espace naturel protégé espagnol situé au nord-est de la province d''Ourense, dans la commune de Rubiá (Valdeoras), et déclaré parc naturel par le gouvernement de Galice. Il couvre 3 151,67 ha pour une altitude moyenne de 684 m : une vallée calcaire aux pentes raides et aux falaises, couverte de forêt méditerranéenne. Il est particulièrement important pour les rapaces, dont l''aigle royal et le faucon pèlerin. Ses nombreuses grottes abritent d''importantes colonies de chauves-souris, les plus importantes de Galice, et l''on y trouve aussi des pâturages de type méditerranéen propres aux montagnes rocheuses.'),
  ('fr', 'serra-de-tramuntana', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'La Serra de Tramuntana (en catalan baléare : [ˈsɛrə ðə tɾəmunˈtanə]) est une chaîne de montagnes orientée sud-ouest-nord-est qui forme l''épine dorsale septentrionale de l''île espagnole de Majorque. C''est également le nom donné à la comarca de la même zone. Le 27 juin [dated source], la Tramuntana Range a été inscrite au patrimoine mondial de l''UNESCO en tant que zone d''une grande importance physique et culturelle.', 'La Serra de Tramuntana est une chaîne de montagnes orientée sud-ouest–nord-est qui forme l''épine dorsale nord de l''île de Majorque ; c''est aussi le nom de la comarque correspondante. La Serra de Tramuntana est inscrite au patrimoine mondial de l''UNESCO pour sa grande valeur physique et culturelle.'),
  ('fr', 'sila-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sila National Park (italien : Parco nazionale della Sila) est un parc national italien en Calabre, situé sur le plateau de la Sila. Établi en 1997, il couvre environ 74 000 hectares (180 000 acres). Ses sommets les plus élevés sont le Mt. Botte Donato (1 928 m), dans la Sila Grande, et le Mt. Gariglione (1 764 m) dans la Sila Piccola. Le parc a été créé par le décret régional du 14 novembre [source datée] et comprend son propre organisme de gestion. Le parc inclut les territoires faisant autrefois partie du Calabria National Park (1968) et protège des zones de grand intérêt environnemental dans la Sila Piccola, la Sila Grande et la Sila Greca, pour un total de 736,95 kilomètres carrés (284,54 sq mi), répartis sur 21 municipalités (comuni) et 6 « communautés de montagne » (comunità montane) à travers les trois provinces calabraises de Catanzaro, Cosenza et Crotone.', 'Le parc national de la Sila (en italien : Parco nazionale della Sila) se trouve en Calabre, sur le plateau de la Sila. Créé en 1997, il couvre environ 74 000 hectares. Ses plus hauts sommets sont le mont Botte Donato (1 928 m), dans la Sila Grande, et le mont Gariglione (1 764 m), dans la Sila Piccola. Le parc reprend des territoires de l''ancien parc national de Calabre (1968) et protège des zones de grand intérêt environnemental dans la Sila Piccola, la Sila Grande et la Sila Greca, sur 21 communes des provinces de Catanzaro, Cosenza et Crotone.'),
  ('fr', 'sjunkhatten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sjunkhatten National Park a été établi en [dated source] dans le comté de Nordland, en Norvège. Le parc consiste en une zone protégée continue de 417,5 kilomètres carrés, incluant une zone maritime de 39,8 kilomètres carrés dans les municipalités de Bodø, Fauske et Sørfold. Le parc est situé sur une péninsule entre le fjord Sørfolda et le Saltfjorden, comprenant un paysage formé par les glaciers, des grottes et des réseaux hydrographiques, des fjords, le grand lac Heggmovatnet, des espèces animales rares et un patrimoine culturel.', 'Le parc national de Sjunkhatten se trouve dans le comté de Nordland, en Norvège. Il forme une zone protégée d''un seul tenant de 417,5 kilomètres carrés, dont 39,8 kilomètres carrés de mer, sur les communes de Bodø, Fauske et Sørfold. Le parc occupe une péninsule entre le fjord de Sørfolda et le Saltfjorden, avec des paysages glaciaires, des grottes et des réseaux hydrographiques, des fjords, le grand lac Heggmovatnet, des espèces animales rares et un patrimoine culturel.'),
  ('fr', 'sjunkhatten-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Sjunkhatten National Park : Sjunkhatten National Park a été établi en [dated source] dans le comté de Nordland, en Norvège.', 'Sjunkhatten National Park : Un parc national de 417,5 km2 sur une péninsule entre le Sørfolda et le Saltfjorden, dans le Nordland.'),
  ('fr', 'sjunkhatten-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Sjunkhatten National Park a été établi en [dated source] dans le comté de Nordland, en Norvège.', 'Un parc national de 417,5 km2 sur une péninsule entre le Sørfolda et le Saltfjorden, dans le Nordland.'),
  ('fr', 'south-harz-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le South Harz Nature Park (allemand : Naturpark Südharz) est situé dans le district de Nordhausen, dans le nord de la Thuringe, en Allemagne. L''acte désignant ce parc naturel dans les montagnes du Harz est entré en vigueur le 31 décembre [source datée] et a ainsi fondé le cinquième parc naturel de Thuringe. Il a une superficie de 267 km². Le parc est géré par l''Association touristique du Sud-Harz (Südharzer Tourismusverband e.V.) conjointement avec le parc naturel de Kyffhäuser.', 'Le parc naturel du Harz méridional (en allemand : Naturpark Südharz) se trouve dans l''arrondissement de Nordhausen, au nord de la Thuringe, en Allemagne. C''est le cinquième parc naturel de Thuringe ; il couvre 267 km² du massif du Harz. Il est géré par l''office de tourisme du Harz méridional (Südharzer Tourismusverband e.V.) en lien avec le parc naturel du Kyffhäuser.'),
  ('fr', 'southern-black-forest-biosphere-area', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'La réserve de biosphère de la Forêt-Noire est située dans le sud de la Forêt-Noire et a été créée en [dated source]. Le bureau est situé dans la ville de Schönau en Forêt-Noire. Après la réserve de biosphère de la Schwäbische Alb créée en [dated source], il s''agit de la deuxième réserve de biosphère du Bade-Wurtemberg. À la mi-juin [dated source], elle a été reconnue par l''UNESCO comme « réserve de biosphère de l''UNESCO ».', 'La réserve de biosphère de la Forêt-Noire se trouve dans le sud de la Forêt-Noire ; son bureau est installé à Schönau im Schwarzwald. Après celle du Jura souabe, c''est la deuxième réserve de biosphère du Bade-Wurtemberg, et l''UNESCO l''a reconnue comme réserve de biosphère.'),
  ('fr', 'southern-black-forest-biosphere-area', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Southern Black Forest Biosphere Area : La réserve de biosphère de la Forêt-Noire est située dans le sud de la Forêt-Noire et a été créée en [dated source].', 'Southern Black Forest Biosphere Area : Une réserve de biosphère UNESCO dans le sud de la Forêt-Noire, dont le bureau se trouve à Schönau.'),
  ('fr', 'southern-black-forest-biosphere-area', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'La réserve de biosphère de la Forêt-Noire est située dans le sud de la Forêt-Noire et a été créée en [dated source].', 'Une réserve de biosphère UNESCO dans le sud de la Forêt-Noire, dont le bureau se trouve à Schönau.'),
  ('fr', 'sparbach-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Pendant le confinement d''avril [source datée], un pin noir a été « gemmé » dans le Naturpark Sparbach. Cet événement a été immortalisé dans un film.', ''),
  ('fr', 'sparbach-nature-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'CLEAR', 'Sparbach Nature Park : Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('fr', 'sparbach-nature-park', 'tagline', 'fields', '{tagline}'::text[], 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('fr', 'tomorr-mountain-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Tomorr Mountain National Park est un parc national fondé en 1956 qui se situe dans le sud de l''Albanie, niché dans les parties centrales et supérieures du massif du Tomorr, s''étendant sur une superficie de 261.06 km2 depuis [dated source], et agrandi pour inclure ses zones de carrières depuis [dated source]. Le parc couvre un territoire de 26,106 ha . La zone relève du comté de Berat et seulement 1,278 ha à l''intérieur du comté d''Elbasan. Le parc a été créé en 1956 et est considéré comme l''une des zones protégées les plus importantes pour le maintien de la biodiversité montagneuse et de l''intégrité de l''écosystème au niveau national. Le parc a été reconnu comme une Important Plant Area d''importance internationale par Plantlife.', 'Le parc national du mont Tomorr, fondé en 1956, se trouve dans le sud de l''Albanie, sur les parties centrales et élevées du massif du Tomorr, et couvre 261,06 km2 (26 106 ha). Il s''étend surtout dans le comté de Berat, avec seulement 1 278 ha dans celui d''Elbasan. Il compte parmi les aires protégées les plus importantes du pays pour la biodiversité et l''intégrité des écosystèmes de montagne, et Plantlife l''a reconnu comme zone importante pour les plantes d''intérêt international.'),
  ('fr', 'tongariro-northern-circuit', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Tongariro Northern Circuit, l''une des Great Walks de Nouvelle-Zélande, propose une randonnée de trois à quatre jours à travers le Tongariro National Park New Zealand. Marqué par la Tongariro Alpine Crossing, une journée complète de paysages grandioses, l''ensemble du sentier s''étend sur 50 kilomètres autour du Mount Ngauruhoe. Environ 2 500 randonneurs ont terminé la marche au cours de la saison [dated source]/22. Cela contraste avec les quelque 25 000 personnes qui parcourent uniquement le segment Tongariro Crossing.', 'Le Tongariro Northern Circuit, l''une des Great Walks de Nouvelle-Zélande, est une randonnée de trois à quatre jours dans le parc national de Tongariro. Point fort du parcours, la Tongariro Alpine Crossing offre une journée entière de paysages saisissants ; l''ensemble du sentier fait environ 50 kilomètres autour du mont Ngauruhoe.'),
  ('fr', 'tongariro-northern-circuit', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Tongariro Northern Circuit : Environ 2 500 randonneurs ont terminé la marche au cours de la saison [dated source]/22.', 'Tongariro Northern Circuit : Une Great Walk de trois à quatre jours dans le parc national de Tongariro, autour du mont Ngauruhoe (50 km).'),
  ('fr', 'tongariro-northern-circuit', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Environ 2 500 randonneurs ont terminé la marche au cours de la saison [dated source]/22.', 'Une Great Walk de trois à quatre jours dans le parc national de Tongariro, autour du mont Ngauruhoe (50 km).'),
  ('fr', 'una-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Una National Park a été établi le 29 mai [source datée] autour des rivières Upper Una River, Krka et Unac. C''est le plus grand parc national de Bosnie-Herzégovine. L''objectif principal du parc est de protéger la rivière Una préservée et ses affluents Krka et Unac, qui le traversent.', 'Le parc national de l''Una s''étend autour du cours supérieur de l''Una et de ses affluents, la Krka et l''Unac. C''est le plus grand parc national de Bosnie-Herzégovine ; il a pour but principal de protéger l''Una, encore préservée, et ces affluents qui le traversent.'),
  ('fr', 'wienerwald-biosphere-reserve', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Wienerwald a été désigné Réserve de biosphère en [dated source] par l''UNESCO. Ce statut protège la grande variété d''éléments naturels et culturels qui rendent cette région si unique et précieuse. Une large gamme de collines boisées alterne avec de vastes prairies, des pâturages et des vergers ainsi que des vignobles et des pelouses sèches - produits de siècles de culture humaine. Quatre parcs naturels et le Lainzer Tiergarten viennois, un vaste parc animalier, figurent parmi les 15 réserves naturelles de cette région.

Les RB sont des écosystèmes reconnus sur la base de critères uniformes et convenus au niveau international, où des modèles d''utilisation durable de la biosphère sont développés, testés et mis en œuvre. En collaboration avec des partenaires locaux et les autorités, les États de Basse-Autriche et de Vienne développent une région modèle pour la durabilité afin de relever les défis du XXIe siècle, dont les générations présentes et futures peuvent bénéficier.', 'Le Wienerwald est classé réserve de biosphère par l''UNESCO. Ce statut protège la grande diversité des éléments naturels et culturels qui font la singularité de la région. Les collines boisées y alternent avec de vastes prairies, des pâturages, des vergers, des vignobles et des pelouses sèches, fruits de siècles de mise en valeur. Quatre parcs naturels et le Lainzer Tiergarten de Vienne, un vaste parc à gibier, figurent parmi les 15 réserves naturelles de la région.

Les réserves de biosphère sont des écosystèmes reconnus selon des critères uniformes et convenus au niveau international, où l''on développe, teste et met en œuvre des modèles d''utilisation durable de la biosphère. Avec les partenaires et autorités locales, la Basse-Autriche et Vienne y développent une région modèle de durabilité pour relever les défis du XXIe siècle.'),
  ('en', 'lierne-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Lierne National Park lies in Lierne Municipality in Trøndelag county, Norway. The 333-square-kilometre park was established on 17 December [dated source] by a royal resolution. The park covers 333 square kilometres of land along the border with Sweden. The park lies east of the populated areas in Lierne Municipality, about 12 kilometres southeast of the village of Sandvika and about 6 kilometres northeast of the village of Mebygda.', 'Lierne National Park lies in Lierne Municipality in Trøndelag county, Norway. The park covers 333 square kilometres along the border with Sweden, east of the populated areas of Lierne, about 12 kilometres southeast of the village of Sandvika and about 6 kilometres northeast of Mebygda.'),
  ('en', 'waterloopbos', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Waterloopbos is a former watercourse at Marknesse in the Noordoostpolder, province of Flevoland. It was a test site of the Waterloopkundige Laboratorium De Voorst, a subsidiary of the Waterloopkundige Laboratorium in Delft. The area is characterized by remains and ruins of laboratory structures. After it lost its function as a place for large-scale piloting of quays and dams, a swamp forest developed. The site, which is part of the approximately 1000 hectares of Voorsterbos, has been owned by the Association of Natural Monuments since [dated source] and has been included in the register of national monuments since [dated source].', 'The Waterloopbos is a former hydraulic test site at Marknesse in the Noordoostpolder, Flevoland. It was a test site of the Waterloopkundige Laboratorium De Voorst, a subsidiary of the Waterloopkundige Laboratorium in Delft, and is marked by the remains and ruins of laboratory structures. After it lost its role as a site for large-scale models of quays and dams, a swamp forest developed. Part of the roughly 1,000-hectare Voorsterbos, it is owned by Natuurmonumenten and is listed in the register of national monuments.'),
  ('fr', 'waterloopbos', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Waterloopbos est un ancien cours d''eau à Marknesse dans le Noordoostpolder, province de Flevoland. C''était un site d''essai du Waterloopkundige Laboratorium De Voorst, une filiale du Waterloopkundige Laboratorium à Delft. La zone est caractérisée par des restes et des ruines de structures de laboratoire. Après avoir perdu sa fonction de lieu d''expérimentation à grande échelle pour les quais et les barrages, une forêt marécageuse s''est développée. Le site, qui fait partie des environ 1000 hectares du Voorsterbos, appartient à l''Association des monuments naturels depuis [dated source] et est inscrit au registre des monuments nationaux depuis [dated source].', 'Le Waterloopbos est un ancien site d''essais hydrauliques à Marknesse, dans le Noordoostpolder (Flevoland). Il servait au laboratoire hydraulique De Voorst, filiale du laboratoire hydraulique de Delft, et conserve les vestiges et ruines de ses installations. Après l''abandon des maquettes de quais et de digues à grande échelle, une forêt marécageuse s''y est développée. Rattaché aux quelque 1 000 hectares du Voorsterbos, le site appartient à Natuurmonumenten et est inscrit au registre des monuments nationaux.')
on conflict (locale, slug, field) do nothing;

do $$
declare n int;
begin
  select count(*) into n from audit_backup.rewrites_20261122_proposals;
  if n <> 320 then
    raise exception 'audit_backup.rewrites_20261122_proposals has % rows, expected 320 (table edited by hand?)', n;
  end if;
end $$;

-- Full-row backups, taken once (a second run never overwrites the first backup).
-- Plain copies (no defaults, generated columns, indexes or triggers), so the backup is an exact snapshot.
create table if not exists audit_backup.rewrites_20261122_destinations as
  select * from public.destinations with no data;
create table if not exists audit_backup.rewrites_20261122_translations as
  select * from public.content_translations with no data;

insert into audit_backup.rewrites_20261122_destinations
select d.* from public.destinations d
where d.slug in (select slug from audit_backup.rewrites_20261122_proposals where locale = 'en')
  and not exists (select 1 from audit_backup.rewrites_20261122_destinations b where b.id = d.id);

insert into audit_backup.rewrites_20261122_translations
select t.* from public.content_translations t
where t.entity_type = 'destination'
  and (t.locale, t.entity_id) in (select locale, slug from audit_backup.rewrites_20261122_proposals where locale <> 'en')
  and not exists (select 1 from audit_backup.rewrites_20261122_translations b where b.id = t.id);

alter table audit_backup.rewrites_20261122_proposals    enable row level security;
alter table audit_backup.rewrites_20261122_destinations enable row level security;
alter table audit_backup.rewrites_20261122_translations enable row level security;
revoke all on audit_backup.rewrites_20261122_proposals, audit_backup.rewrites_20261122_destinations,
              audit_backup.rewrites_20261122_translations from public;
do $$
declare r text;
begin
  foreach r in array array['anon', 'authenticated'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke all on audit_backup.rewrites_20261122_proposals, audit_backup.rewrites_20261122_destinations, '
                     'audit_backup.rewrites_20261122_translations from %I', r);
    end if;
  end loop;
end $$;

-- ============================================================================================
-- 2. Apply. One UPDATE per proposal, guarded by "current text = reviewed old text".
-- ============================================================================================
create temp table fix_log (
  locale text, slug text, field text, decision text,
  status text,        -- applied | already-applied | changed-since-review | row-missing
  rows_changed int
) on commit drop;

do $$
declare
  p   record;
  cur text;
  hit int;
  n   int;
begin
  for p in select * from audit_backup.rewrites_20261122_proposals order by locale, slug, field loop
    n := 0;
    if p.locale = 'en' then
      select count(*),
             max(case p.col when 'tagline' then d.tagline
                            when 'seo_description' then d.seo_description
                            else d.travel_plan #>> p.path end)
        into hit, cur
        from public.destinations d where d.slug = p.slug;
    else
      select count(*), max(t.fields #>> p.path) into hit, cur
        from public.content_translations t
       where t.entity_type = 'destination' and t.entity_id = p.slug and t.locale = p.locale;
    end if;

    if hit > 1 then
      raise exception 'More than one row for % % — refusing to guess', p.locale, p.slug;
    end if;

    if hit = 0 or cur is null then
      insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'row-missing', 0);
      continue;
    elsif cur = p.new_text then
      insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'already-applied', 0);
      continue;
    elsif cur <> p.old_text then
      insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'changed-since-review', 0);
      continue;
    end if;

    if p.locale = 'en' and p.col = 'tagline' then
      update public.destinations set tagline = p.new_text, updated_at = now()
       where slug = p.slug and tagline = p.old_text;
    elsif p.locale = 'en' and p.col = 'seo_description' then
      update public.destinations set seo_description = p.new_text, updated_at = now()
       where slug = p.slug and seo_description = p.old_text;
    elsif p.locale = 'en' then
      update public.destinations set travel_plan = jsonb_set(travel_plan, p.path, to_jsonb(p.new_text), false),
                                     updated_at = now()
       where slug = p.slug and travel_plan #>> p.path = p.old_text;
    else
      update public.content_translations set fields = jsonb_set(fields, p.path, to_jsonb(p.new_text), false),
                                             updated_at = now()
       where entity_type = 'destination' and entity_id = p.slug and locale = p.locale
         and fields #>> p.path = p.old_text;
    end if;
    get diagnostics n = row_count;
    if n <> 1 then
      raise exception 'Expected 1 changed row for % % %, got %', p.locale, p.slug, p.field, n;
    end if;
    insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'applied', n);
  end loop;
end $$;

-- ============================================================================================
-- 3. Final checks (any failure aborts the whole transaction).
-- ============================================================================================
do $$
declare bad int;
begin
  -- fix_log covers every proposal exactly once.
  select count(*) into bad from audit_backup.rewrites_20261122_proposals p
  where (select count(*) from fix_log f where f.locale = p.locale and f.slug = p.slug and f.field = p.field) <> 1;
  if bad > 0 then raise exception 'fix_log check failed: % proposals not logged exactly once', bad; end if;

  -- Every applied / already-applied field now holds exactly the reviewed new text.
  select count(*) into bad
  from fix_log f join audit_backup.rewrites_20261122_proposals p using (locale, slug, field)
  left join public.destinations d on f.locale = 'en' and d.slug = f.slug
  left join public.content_translations t on f.locale <> 'en' and t.entity_type = 'destination'
                                          and t.entity_id = f.slug and t.locale = f.locale
  where f.status in ('applied', 'already-applied')
    and (case when f.locale <> 'en' then t.fields #>> p.path
              when p.col = 'tagline' then d.tagline
              when p.col = 'seo_description' then d.seo_description
              else d.travel_plan #>> p.path end) is distinct from p.new_text;
  if bad > 0 then raise exception 'Value check failed for % fields', bad; end if;

  -- JSON structure (keys, array lengths, non-string values) identical to the backup.
  select count(*) into bad
  from public.content_translations t
  join audit_backup.rewrites_20261122_translations b on b.id = t.id
  where translation_fix.jsonb_shape(t.fields) is distinct from translation_fix.jsonb_shape(b.fields)
     or translation_fix.identity_values(t.fields) is distinct from translation_fix.identity_values(b.fields)
     or t.status is distinct from b.status;
  if bad > 0 then raise exception 'Structure/identity/status check failed for % translation rows', bad; end if;

  select count(*) into bad
  from public.destinations d
  join audit_backup.rewrites_20261122_destinations b on b.id = d.id
  where translation_fix.jsonb_shape(d.travel_plan) is distinct from translation_fix.jsonb_shape(b.travel_plan)
     or translation_fix.identity_values(d.travel_plan) is distinct from translation_fix.identity_values(b.travel_plan)
     or d.status is distinct from b.status or d.name is distinct from b.name;
  if bad > 0 then raise exception 'Structure/identity/status check failed for % destinations', bad; end if;

  -- No placeholder token in any written text.
  select count(*) into bad from audit_backup.rewrites_20261122_proposals
  where new_text ~ '\[(dated source|source datée|datierter Quelle|datiert Quelle)';
  if bad > 0 then raise exception 'Token check failed: % new texts contain a placeholder', bad; end if;
end $$;

-- Result (first run: applied; second run: already-applied; edited since review: changed-since-review).
select locale, decision, status, count(*) as fields, sum(rows_changed) as rows_changed
from fix_log group by 1, 2, 3 order by 1, 2, 3;

-- Fields skipped because their text no longer matches the review (rewrite these by hand).
select locale, slug, field, status from fix_log
where status in ('changed-since-review', 'row-missing') order by 1, 2, 3;

commit;

-- ============================================================================================
-- ROLLBACK (run on its own, only if needed). Restores each rewritten field from the backup, but only
-- where the field still holds the text this script wrote (later edits are left alone).
-- Remove the comment markers /* and */ around the block below, then run it.
-- ============================================================================================
